window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["U9"]={"deck":"U9","slides":[{"p":1,"title":"09 프랭크 로이드 라이트(Frank Lloyd Wright), 알바 알토(Alvar Aalto) (표지)","terms":["Frank Lloyd Wright","Alvar Aalto","Organic Architecture"],"pass1":[{"kind":"say","lines":["9단원 표지예요. 하늘색 띠에 두 사람 이름만 있어요.","**프랭크 로이드 라이트(Frank Lloyd Wright)** 와 **알바 알토(Alvar Aalto)** 예요.","두 사람을 묶는 말은 **유기적 건축(Organic Architecture)** 이에요.","나무가 땅에서 자라듯, 건물이 자연과 한 몸이 되는 건축이에요."]},{"kind":"goal","items":["이 범위(p.1-18)에서 할 일","**프랭크 로이드 라이트(Frank Lloyd Wright)** 의 집이 어떻게 '상자' 를 깼는지 봐요.","**낙수장(Falling Water, House Kaufmann)** 으로 유기적 건축의 뜻을 잡아요.","주문도 같이 떠올려요. 기계 시대에 건축은 어떻게 생겨야 하나?"]}],"pass2":[{"kind":"points","head":"9단원에서 만날 차례","items":["1) **프랭크 로이드 라이트(Frank Lloyd Wright)** 와 **프레이리형 주택** (p.2-8)","2) **유니티 교회** 와 **탤리에신(Taliesin)** (p.9-11)","3) **낙수장(Falling Water, House Kaufmann)** 과 **유기적 건축(Organic Architecture)** (p.12-17)","4) **존슨 왁스 본부(S.C. Johnson Wax Headquarters)** 와 구겐하임 미술관 (p.18-21)","5) **알바 알토(Alvar Aalto)** 와 그의 주택들 (p.22-35)"]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.04,0.24,0.88,0.1],"c":[0,0.1922,0.968,0.1956],"r":6.5985,"img":"img/U9/walk/p001_21_01.jpg","say":"09 다음에 첫 번째 사람: 프랭크 로이드 라이트(Frank Lloyd Wright)."},{"b":[0.145,0.355,0.4,0.07],"c":[0.125,0.335,0.44,0.11],"r":5.3333,"img":"img/U9/walk/p001_21_02.jpg","say":"두 번째 사람: 알바 알토(Alvar Aalto). 핀란드 건축가예요(p.22부터)."}]}},{"p":2,"title":"프랭크 로이드 라이트(Frank Lloyd Wright, 1867-1959)","terms":["Frank Lloyd Wright","단크마어 아들러","Louis Sullivan","form follows functions","시카고 학파"],"pass1":[{"kind":"say","lines":["의자에 앉은 노신사 사진이 **프랭크 로이드 라이트(Frank Lloyd Wright)** 예요.","1867년에 태어나 1959년까지 살았어요. 미국 위스콘신 출신이에요.","스승은 2단원 **시카고 학파** 의 **루이스 설리번(Louis Sullivan)** 이에요.","설리번의 유명한 한마디가 이 쪽에 다시 나와요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**단크마어 아들러**: 라이트가 건축을 배운 사무실의 건축가예요(1844-1910).","**루이스 설리번(Louis Sullivan)**: 아들러와 같은 사무실의 **시카고 학파** 건축가예요.","**형태는 기능을 따른다(form follows functions)**: 건물 모양은 쓰임새에서 나와야 한다는 설리번의 말이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**프랭크 로이드 라이트(Frank Lloyd Wright)**, 1867-1959.","위스콘신에서 출생, 개척자의 성향을 가지고 있었어요.","**단크마어 아들러**(1844-1910)와 **루이스 설리번(Louis Sullivan)** 의 사무실에서 건축 수업을 했어요.","설리번의 말: **형태는 기능을 따른다(form follows functions)**.","형태의 미는 필연적으로 기능을 표현하는 데서 나온다는 의미예요.","즉 표현을 정직하게 하는 것이 아름다운 건물을 창조하는 데 필수적인 선결조건이라는 뜻이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**형태는 기능을 따른다(form follows functions)** 는 누구의 말일까요?","choices":["**프랭크 로이드 라이트(Frank Lloyd Wright)**","**루이스 설리번(Louis Sullivan)**","**단크마어 아들러**"],"a":1,"why":"설리번의 말이에요. 라이트는 그 사무실에서 배운 사람이에요."},{"kind":"check","q":"**프랭크 로이드 라이트(Frank Lloyd Wright)** 의 생몰 연도로 옳은 것은 무엇일까요?","choices":["1844-1910","1867-1959","1898-1976"],"a":1,"why":"1867-1959예요. 1844-1910은 아들러, 1898-1976은 알토예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드의 설리번 연도 '1986-1924' 는 오타로 보여요. 2단원 표기는 1856-1924예요.","'형태는 기능을 따른다' 의 주인은 라이트가 아니라 **루이스 설리번(Louis Sullivan)** 이에요.","슬라이드 영어 표기는 'form follows functions' 예요. 옮겨 쓸 때 슬라이드 표기를 따라요."]},{"kind":"english","head":"논술 답안: 라이트의 배경","en":"프랭크 로이드 라이트(1867-1959)는 위스콘신에서 출생하여 개척자의 성향을 가졌으며, 단크마어 아들러와 루이스 설리번의 사무실에서 건축 수업을 받았다.","ko":"출생지, 성향, 스승 두 사람을 한 문장에 넣어요.","tip":"'위스콘신 개척자, 설리번 사무실' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.045,0.06,0.47,0.05],"c":[0.0215,0.03,0.517,0.11],"r":6.2667,"img":"img/U9/walk/p002_22_01.jpg","say":"제목: Frank Lloyd Wright (1867-1959)."},{"b":[0.09,0.14,0.53,0.05],"c":[0.0635,0.1061,0.583,0.1178],"r":6.5988,"img":"img/U9/walk/p002_22_02.jpg","say":"위스콘신 출생, 개척자의 성향."},{"b":[0.09,0.195,0.87,0.055],"c":[0.043,0.1258,0.957,0.1933],"r":6.6011,"img":"img/U9/walk/p002_22_03.jpg","say":"아들러(1844-1910)와 설리번의 사무실. 설리번 연도가 1986-1924로 적혀 있어요."},{"b":[0.09,0.26,0.66,0.11],"c":[0.057,0.2417,0.726,0.1467],"r":6.5985,"img":"img/U9/walk/p002_22_04.jpg","say":"설리번의 말 '형태는 기능을 따른다' 와 그 뜻이에요."},{"b":[0.035,0.425,0.9,0.05],"c":[0,0.35,0.99,0.2],"r":6.6,"img":"img/U9/walk/p002_22_05.jpg","say":"화살표 문장: 정직한 표현이 아름다운 건물의 선결조건이라는 뜻."},{"b":[0.095,0.52,0.28,0.46],"c":[0.081,0.494,0.308,0.506],"r":0.8116,"img":"img/U9/walk/p002_22_06.jpg","say":"라이트의 사진이에요. 캡션: 프랭크 로이드 라이트(Frank Lloyd Wright, 1867-1959)."}]}},{"p":3,"title":"프레이리형 주택(대초원 주택)의 속성과 특징","terms":["프레이리형 주택","오크파크","리버사이드","윈슬로 하우스","House Willits","Robie House","타탄 체크의 그리드 플랜","완만한 경사지붕","수평 띠","부가적인 벽"],"pass1":[{"kind":"analogy","head":"대초원처럼 낮고 길게","scene":"넓은 들판에 납작하게 엎드린 집을 떠올려 보세요. 하늘로 솟지 않고 옆으로 길게 깔려요.","map":[["끝없이 넓은 대초원","**프레이리형 주택**(대초원 주택)"],["들판의 지평선","창문을 이어 만든 **수평 띠**"],["낮게 덮은 모자 챙","처마가 긴 **완만한 경사지붕**"]]},{"kind":"say","lines":["아래 그림은 1900년 잡지를 위한 집 계획안이에요.","지붕이 낮고, 옆으로 길게 뻗어 있죠. 이것이 **프레이리형 주택** 의 모습이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**프레이리형 주택**: 대초원 주택이라고도 해요. 시카고 근교의 집들이에요.","**타탄 체크의 그리드 플랜**: 체크무늬 같은 격자를 깔고 방을 놓는 평면이에요.","**수평 띠**: 창문을 정리해 가로로 길게 이은 띠예요.","**부가적인 벽**: 건물 본체에 덧붙여 쓰는 벽이에요."]},{"kind":"points","head":"프레이리형 주택 (대초원 주택)","items":["시카고 근교의 **오크파크** 와 **리버사이드** 에 세워진 주택들이에요.","**윈슬로 하우스**(1894) → **윌리츠 하우스(House Willits)**(1903) → **로비 하우스(Robie House)**(1908)."]},{"kind":"points","head":"프레이리형 주택의 속성과 특징","items":["미국 전통주택의 전통 계승: 소박함, 불필요한 형식적인 방의 배제.","**타탄 체크의 그리드 플랜** 사용.","**완만한 경사지붕** 의 처마 강조.","창문을 정리하여 **수평 띠** 를 만드는 것.","**부가적인 벽** 의 사용.","수평선과 수직성의 대비, 긴장감."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**프레이리형 주택** 세 작품을 연도 순서대로 바르게 놓은 것은 무엇일까요?","choices":["**로비 하우스(Robie House)** → **윌리츠 하우스(House Willits)** → **윈슬로 하우스**","**윈슬로 하우스** → **윌리츠 하우스(House Willits)** → **로비 하우스(Robie House)**","**윌리츠 하우스(House Willits)** → **윈슬로 하우스** → **로비 하우스(Robie House)**"],"a":1,"why":"윈슬로(1894), 윌리츠(1903), 로비(1908) 순서예요."},{"kind":"check","q":"**프레이리형 주택** 이 세워진 시카고 근교 두 지역은 어디일까요?","choices":["**오크파크** 와 **리버사이드**","라신과 스프링 그린","브레슬라우와 포츠담"],"a":0,"why":"오크파크와 리버사이드예요. 라신은 존슨 왁스 본부, 스프링 그린은 탤리에신이에요."},{"kind":"check","q":"다음 중 **프레이리형 주택** 의 속성과 특징이 아닌 것은 무엇일까요?","choices":["**타탄 체크의 그리드 플랜** 사용","**완만한 경사지붕** 의 처마 강조","철골에 테라코타 외벽, 3부분 분할","창문을 정리하여 **수평 띠** 를 만듦"],"a":2,"why":"철골, 테라코타, 3부분 분할은 2단원 시카고 학파의 고층 건물 이야기예요."},{"kind":"english","head":"논술 답안: 프레이리형 주택","en":"프레이리형 주택은 미국 전통주택의 소박함을 계승하고, 타탄 체크의 그리드 플랜, 완만한 경사지붕의 처마 강조, 창문의 수평 띠, 부가적인 벽을 사용하였다.","ko":"전통 계승 하나와 설계 특징 넷을 이어 써요. 끝에 '수평선과 수직성의 대비, 긴장감' 을 붙이면 더 좋아요.","tip":"'그리드, 처마, 띠, 벽, 대비' 다섯 단어로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.05,0.4,0.2],"c":[0.02,0.034,0.44,0.232],"r":2.5287,"img":"img/U9/walk/p003_23_01.jpg","say":"왼쪽 위: 속성과 특징의 첫 줄. 미국 전통주택 계승(소박함, 형식적인 방 배제)."},{"b":[0.085,0.32,0.41,0.255],"c":[0.0645,0.304,0.451,0.287],"r":2.0952,"img":"img/U9/walk/p003_23_02.jpg","say":"설계 특징 다섯 줄: 그리드 플랜, 처마, 수평 띠, 부가적인 벽, 수평과 수직의 대비."},{"b":[0.55,0.05,0.38,0.32],"c":[0.531,0.034,0.418,0.352],"r":1.5833,"img":"img/U9/walk/p003_23_03.jpg","say":"오른쪽: 대초원 주택. 오크파크와 리버사이드, 윈슬로 1894, 윌리츠 1903, 로비 1908."},{"b":[0.46,0.565,0.45,0.07],"c":[0.4375,0.545,0.495,0.11],"r":6.0,"img":"img/U9/walk/p003_23_04.jpg","say":"그림 제목: 1900 'A Home in a Prairie Town', 잡지 'Ladies' Home Journal' 을 위한 계획안."},{"b":[0.2,0.72,0.77,0.27],"c":[0.153,0.698,0.847,0.302],"r":3.7395,"img":"img/U9/walk/p003_23_05.jpg","say":"계획안 그림: 낮은 지붕이 겹겹이 옆으로 뻗고 창이 가로로 이어져요."}]}},{"p":4,"title":"윌리츠 하우스(House Willits), 미국 일리노이, 1903","terms":["House Willits","십자형 평면","개방형 벽난로","빌트인 좌석","공간의 연속성","상자 형태의 파괴","프레이리형 주택"],"pass1":[{"kind":"analogy","head":"상자를 깨다","scene":"상자 뚜껑을 열고 네 벽을 바깥으로 활짝 펼쳐 놓은 모습을 떠올려 보세요.","map":[["닫힌 상자","방이 꽉 막힌 옛 집"],["네 방향으로 펼친 벽","밖으로 뻗은 **십자형 평면**"],["상자를 깼다","**상자 형태의 파괴**"]]},{"kind":"say","lines":["위 왼쪽은 열십자 모양 평면도, 아래는 외관 사진이에요.","**윌리츠 하우스(House Willits)** 예요. **프레이리형 주택** 의 대표작이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**십자형 평면**: 열십자 모양으로 방들이 사방으로 뻗은 평면이에요.","**개방형 벽난로**: 벽으로 가두지 않고 트인 곳에 둔 벽난로예요.","**빌트인 좌석**: 벽이나 바닥에 붙박이로 만든 의자예요.","**공간의 연속성**: 방과 방이 끊기지 않고 이어지는 느낌이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**프랭크 로이드 라이트(Frank Lloyd Wright)**, **윌리츠 하우스(House Willits)**, 미국 일리노이, 1903.","**십자형 평면** 이 외부로 확장돼요.","회반죽의 흰 벽과 짙은 나무 프레임이 조화된 외관이에요.","**빌트인 좌석** 으로 둘러싸인 **개방형 벽난로** 가 평면의 핵심을 형성해요.","**공간의 연속성**.","자신이 디자인한 가구로 많은 시험적 작품을 완성했어요.","\"상자 형태를 파괴했다\". 이것을 줄여 **상자 형태의 파괴** 라고 기억해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**윌리츠 하우스(House Willits)** 에서 평면의 핵심을 이루는 것은 무엇일까요?","choices":["**빌트인 좌석** 으로 둘러싸인 **개방형 벽난로**","3층 높이의 **갤러리층**","콘크리트 기둥의 **접시형 요소**"],"a":0,"why":"빌트인 좌석으로 둘러싸인 개방형 벽난로예요. 갤러리층은 유니티 교회, 접시형 요소는 존슨 왁스 본부예요."},{"kind":"check","q":"\"상자 형태를 파괴했다\" 는 문구가 붙은 작품은 무엇일까요?","choices":["**로비 하우스(Robie House)**","**유니티 교회**","**윌리츠 하우스(House Willits)**"],"a":2,"why":"윌리츠 하우스 슬라이드의 문구예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**윌리츠 하우스(House Willits)** 는 일리노이, 1903. **로비 하우스(Robie House)** 는 시카고, 1908이에요.","윌리츠는 '회반죽 흰 벽 + 짙은 나무 프레임', 로비는 '연속 창문 띠가 벽' 이에요."]},{"kind":"english","head":"논술 답안: 윌리츠 하우스","en":"윌리츠 하우스(1903)는 십자형 평면이 외부로 확장되고, 빌트인 좌석으로 둘러싸인 개방형 벽난로가 평면의 핵심을 형성하여 상자 형태를 파괴하였다.","ko":"평면, 벽난로, 상자 파괴 세 가지예요.","tip":"'십자, 벽난로, 상자 파괴' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.07,0.065,0.14,0.04],"c":[0.04,0.03,0.2,0.11],"r":2.4242,"img":"img/U9/walk/p004_22_01.jpg","say":"제목: 윌리츠 하우스."},{"b":[0.06,0.145,0.36,0.35],"c":[0.042,0.1275,0.396,0.385],"r":1.3714,"img":"img/U9/walk/p004_22_02.jpg","say":"평면도: 가운데에서 네 방향으로 뻗은 십자형 평면이에요."},{"b":[0.43,0.05,0.535,0.35],"c":[0.4032,0.0325,0.5885,0.385],"r":2.0381,"img":"img/U9/walk/p004_22_03.jpg","say":"특징 다섯 줄: 십자형 평면, 흰 벽과 나무 프레임, 벽난로, 연속성, 가구."},{"b":[0.43,0.47,0.25,0.045],"c":[0.4175,0.4375,0.275,0.11],"r":3.3333,"img":"img/U9/walk/p004_22_04.jpg","say":"따옴표 문장: \"상자 형태를 파괴했다\"."},{"b":[0.19,0.515,0.645,0.415],"c":[0.1577,0.4943,0.7095,0.4565],"r":2.0723,"img":"img/U9/walk/p004_22_05.jpg","say":"외관 사진: 흰 벽에 짙은 나무 띠, 낮은 지붕이 옆으로 길게 나와요."},{"b":[0.37,0.95,0.45,0.04],"c":[0.3475,0.89,0.495,0.11],"r":6.0,"img":"img/U9/walk/p004_22_06.jpg","say":"캡션: 프랭크 로이드 라이트, House Willits, 미국 일리노이, 1903."}]}},{"p":5,"title":"캡션 없는 실내 사진 두 장 (거실과 식당)","terms":["개방형 벽난로","프레이리형 주택","Frank Lloyd Wright"],"pass1":[{"kind":"say","lines":["글자 없이 실내 사진 두 장만 있어요.","왼쪽은 벽돌 벽난로가 있는 거실, 오른쪽은 격자 천장의 식당이에요.","슬라이드에 집 이름이 적혀 있지 않아요. 보이는 것만 기억해요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽: 벽돌로 쌓은 넓은 벽난로가 방 한쪽을 차지해요.","왼쪽: 바닥에 낮은 방석과 흰 소파, 짙은 나무 띠가 천장과 벽을 둘러요.","오른쪽: 천장이 나무 격자로 나뉘고, 칸마다 색유리 판이 들어 있어요.","오른쪽: 등받이가 높은 나무 의자들이 긴 식탁을 둘러싸요.","앞 쪽에서 배운 **개방형 벽난로**, 짙은 나무 프레임을 실내에서 다시 보는 느낌이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["캡션이 없는 쪽이에요. 어느 집인지 슬라이드에 적혀 있지 않아요.","시험 답안에 이 사진의 집 이름을 지어 쓰지 않아요. 앞뒤 쪽(윌리츠 p.4, 로비 p.6)의 캡션만 써요."]}],"walk":{"head":null,"parts":[{"b":[0.02,0.225,0.575,0.525],"c":[0,0.1988,0.6325,0.5775],"r":1.4603,"img":"img/U9/walk/p005_21_01.jpg","say":"왼쪽 사진: 벽돌 벽난로가 있는 거실. 짙은 나무 띠가 흰 벽과 천장을 나눠요."},{"b":[0.6,0.16,0.38,0.655],"c":[0.581,0.1273,0.418,0.7205],"r":0.7735,"img":"img/U9/walk/p005_21_02.jpg","say":"오른쪽 사진: 나무 격자 천장에 색유리 판, 등받이 높은 의자가 놓인 식당."}]}},{"p":6,"title":"로비 하우스(Robie House), 미국 시카고, 1908 (사진, 평면, 입면 스케치)","terms":["Robie House","프레이리형 주택","수평 띠","완만한 경사지붕","Frank Lloyd Wright"],"pass1":[{"kind":"say","lines":["붉은 벽돌 집 사진, 평면도 두 장, 그리고 스케치가 있어요.","**로비 하우스(Robie House)** 예요. 시카고, 1908년이에요.","지붕이 얇고 길게 옆으로 뻗어 있어요. 대초원의 지평선 같아요.","**프레이리형 주택** 세 작품 가운데 마지막(1908)이에요."]}],"pass2":[{"kind":"points","head":"이 쪽에서 볼 것","items":["**프랭크 로이드 라이트(Frank Lloyd Wright)**, **로비 하우스(Robie House)**, 미국 시카고, 1908.","그림 속 설명: 로비 하우스(1908), 시카고. 라이트의 뛰어난 작품 중 하나이다.","그림 속 설명: 공간적 자유로움, 내, 외부의 통합과 세련된 설비 부분은 뛰어난 랜드마크를 형성한다.","위 평면 이름표: PORCH, LIVING, FIRE, DINING, BALCONY, GUEST, KITCHEN, SERVANT.","가운데 평면 이름표: 거실 부분, 식당 공간, 손님 방, 부엌, 하인 방, 중간층 평면. 스케치에는 2층 평면."]},{"kind":"points","head":"평면을 읽는 법","items":["LIVING(거실)과 DINING(식당)이 한 줄로 길게 이어져요.","그 가운데에 FIRE(벽난로)가 있어요. 벽난로가 집의 중심이에요.","앞쪽으로 BALCONY(발코니)가 길게 붙어 **수평 띠** 를 강조해요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**로비 하우스(Robie House)** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["일리노이, 1903","시카고, 1908","위스콘신 라신, 1939"],"a":1,"why":"시카고, 1908이에요. 일리노이 1903은 윌리츠 하우스예요."},{"kind":"check","q":"**로비 하우스(Robie House)** 평면에서 LIVING 과 DINING 사이에 놓인 것은 무엇일까요?","choices":["FIRE(벽난로)","PULPIT(설교단)","KITCHEN(부엌)"],"a":0,"why":"FIRE, 벽난로예요. 라이트 집에서 벽난로는 집의 중심이에요."}],"walk":{"head":{"b":[0.0499,0.028,0.1242,0.04],"c":[0.012,0.012,0.2,0.072],"r":3.7037,"img":"img/U9/walk/p006_h.jpg"},"parts":[{"b":[0.01,0.1,0.545,0.445],"c":[0,0.0778,0.5995,0.4895],"r":1.633,"img":"img/U9/walk/p006_22_01.jpg","say":"외관 사진: 붉은 벽돌, 길게 뻗은 낮은 지붕과 처마."},{"b":[0.555,0.07,0.425,0.23],"c":[0.5325,0.054,0.4675,0.262],"r":2.3791,"img":"img/U9/walk/p006_22_02.jpg","say":"위 평면: LIVING, FIRE, DINING 이 한 줄로 이어지고 앞에 BALCONY."},{"b":[0.58,0.335,0.36,0.23],"c":[0.562,0.319,0.396,0.262],"r":2.0153,"img":"img/U9/walk/p006_22_03.jpg","say":"가운데 평면: 거실 부분, 식당 공간, 손님 방, 부엌, 하인 방(중간층 평면)."},{"b":[0.24,0.55,0.48,0.115],"c":[0.216,0.534,0.528,0.147],"r":4.7891,"img":"img/U9/walk/p006_22_04.jpg","say":"그림 속 설명 두 개: 뛰어난 작품, 내, 외부의 통합과 랜드마크."},{"b":[0.25,0.665,0.7,0.28],"c":[0.215,0.649,0.77,0.312],"r":3.2906,"img":"img/U9/walk/p006_22_05.jpg","say":"입면 스케치: 얇은 지붕판이 좌우로 길게 튀어나와요. 2층 평면 표시."},{"b":[0.27,0.935,0.53,0.04],"c":[0.2435,0.8822,0.583,0.1178],"r":6.5988,"img":"img/U9/walk/p006_22_06.jpg","say":"캡션: 프랭크 로이드 라이트, 로비 하우스(Robie House), 미국 시카고, 1908."}]}},{"p":7,"title":"로비 하우스(Robie House)의 특징","terms":["Robie House","수평 띠","입체파 성격의 외부 형태"],"pass1":[{"kind":"say","lines":["**로비 하우스(Robie House)** 의 실내 하나, 바깥 벽 둘이에요.","창문이 줄줄이 이어져서 그 자체가 벽처럼 보여요.","땅에 착 붙어 옆으로 길게 누운 집이에요.","각진 면들이 맞물린 바깥 모양을 **입체파 성격의 외부 형태** 라고 해요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**입체파 성격의 외부 형태**: 날카로운 각진 면들이 절묘하게 만나는 외관이에요.","**수평 띠**: 창문을 가로로 길게 이은 띠예요. 로비에서는 이 띠가 곧 벽이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["연속적인 창문 띠로 벽체 형성: 벽체는 지붕과 분리.","날카로운 각진 면들이 절묘하게 만나는 '입체파' 성격의 외부 형태.","지면에 견고하게 부착: 대지의 수평선을 중요시."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**로비 하우스(Robie House)** 의 특징으로 옳지 않은 것은 무엇일까요?","choices":["연속적인 창문 띠로 벽체 형성","벽체는 지붕과 분리","콘크리트 자체를 외벽 재료로 사용","지면에 견고하게 부착"],"a":2,"why":"콘크리트를 외벽 재료로 쓴 것은 유니티 교회(1907)예요."},{"kind":"english","head":"논술 답안: 로비 하우스","en":"로비 하우스(1908)는 연속적인 창문 띠로 벽체를 형성하고 벽체를 지붕과 분리하였으며, '입체파' 성격의 외부 형태로 지면에 견고하게 부착되어 대지의 수평선을 중요시하였다.","ko":"창문 띠, 지붕 분리, 입체파, 지면 부착 네 가지예요.","tip":"'띠, 분리, 입체, 부착' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.115,0.49,0.37],"c":[0,0.0965,0.539,0.407],"r":1.7658,"img":"img/U9/walk/p007_22_01.jpg","say":"실내 사진: 창이 한쪽 벽을 따라 줄지어 이어지고, 천장에 나무 띠가 흘러요."},{"b":[0.55,0.13,0.37,0.32],"c":[0.5315,0.114,0.407,0.352],"r":1.5417,"img":"img/U9/walk/p007_22_02.jpg","say":"특징 세 줄: 창문 띠가 벽, 입체파 외형, 지면에 견고하게 부착."},{"b":[0.025,0.505,0.475,0.42],"c":[0.0013,0.484,0.5225,0.462],"r":1.5079,"img":"img/U9/walk/p007_22_03.jpg","say":"왼쪽 아래: 벽돌 벽 사이로 창문이 한 줄로 길게 이어져요."},{"b":[0.565,0.505,0.405,0.42],"c":[0.5447,0.484,0.4455,0.462],"r":1.2857,"img":"img/U9/walk/p007_22_04.jpg","say":"오른쪽 아래: 각진 면들이 층층이 만나는 외관, 지붕이 길게 튀어나와요."},{"b":[0.27,0.935,0.53,0.04],"c":[0.2435,0.8822,0.583,0.1178],"r":6.5988,"img":"img/U9/walk/p007_22_05.jpg","say":"캡션: 프랭크 로이드 라이트, 로비 하우스(Robie House), 미국 시카고, 1908."}]}},{"p":8,"title":"라이트 주택의 특징","terms":["Frank Lloyd Wright","상호관입","내외부 공간의 모호한 구분","테라스","개방형 벽난로","완만한 경사지붕"],"pass1":[{"kind":"say","lines":["앞의 집들을 한 장으로 묶은 정리 쪽이에요.","**프랭크 로이드 라이트(Frank Lloyd Wright)** 는 사람과 자연의 관계를 집으로 표현했어요.","그래서 안과 밖이 섞이고, 벽난로가 집의 한가운데에 와요."]},{"kind":"recap","items":["라이트 집 한 줄 정리","공간이 서로 파고들어요(**상호관입**).","안과 밖의 경계가 흐려요(**내외부 공간의 모호한 구분**).","**테라스** 가 집과 풍경을 잇고, 벽난로가 집의 중심이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**상호관입**: 공간과 공간이 서로 파고들어 겹치는 것이에요.","**내외부 공간의 모호한 구분**: 안과 밖의 경계를 흐리게 한 것이에요.","**테라스**: 집과 바깥 풍경을 이어 주는 열린 바닥이에요."]},{"kind":"points","head":"라이트 주택의 특징 (슬라이드 그대로)","items":["인간과 자연의 관계에 대한 자신의 느낌을 표현하는 개인적인 건축양식을 발전시킴.","**상호관입** 한 공간.","**내외부 공간의 모호한 구분**.","주택과 풍경을 이어주는 **테라스**: 유기적으로 해석된 개방 공간.","벽난로가 수평요소와 수직 요소를 결합: 주택 전체의 절정이자 중심(가정의 난로가 주는 실존적 의미를 중시).","수평적인 경사지붕. 벽돌이나 목재와 같은 단순한 재료 사용: 소박한 미국의 건축에 대한 독창적 해석."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"라이트 주택에서 '주택 전체의 절정이자 중심' 으로 설명되는 것은 무엇일까요?","choices":["**테라스**","벽난로","창문 **수평 띠**"],"a":1,"why":"벽난로예요. 수평요소와 수직 요소를 결합하고, 가정의 난로가 주는 실존적 의미를 중시했어요."},{"kind":"check","q":"라이트 주택에서 **테라스** 를 설명한 말로 옳은 것은 무엇일까요?","choices":["주택과 풍경을 이어주는 유기적으로 해석된 개방 공간","신과 현세를 대비시키는 공간","작품보다 관람객을 전시하는 공간"],"a":0,"why":"주택과 풍경을 이어주는 테라스, 유기적으로 해석된 개방 공간이에요."},{"kind":"english","head":"논술 답안: 라이트 주택의 특징","en":"라이트는 인간과 자연의 관계를 표현하는 개인적 건축양식을 발전시켰으며, 상호관입한 공간, 내외부 공간의 모호한 구분, 풍경을 잇는 테라스, 중심이 되는 벽난로를 특징으로 한다.","ko":"공간 셋(상호관입, 모호한 구분, 테라스)과 벽난로 하나예요. 지붕과 재료를 붙이면 더 좋아요.","tip":"'섞고, 흐리고, 잇고, 모은다(벽난로)' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.045,0.05,0.89,0.095],"c":[0.0005,0,0.979,0.1978],"r":6.5993,"img":"img/U9/walk/p008_22_01.jpg","say":"제목 줄: 인간과 자연의 관계에 대한 느낌을 표현하는 개인적인 건축양식."},{"b":[0.095,0.16,0.65,0.155],"c":[0.0625,0.144,0.715,0.187],"r":5.098,"img":"img/U9/walk/p008_22_02.jpg","say":"상호관입한 공간, 내외부 공간의 모호한 구분, 테라스."},{"b":[0.095,0.315,0.845,0.1],"c":[0.0527,0.2711,0.9295,0.1878],"r":6.5992,"img":"img/U9/walk/p008_22_03.jpg","say":"벽난로: 수평요소와 수직 요소를 결합, 주택 전체의 절정이자 중심."},{"b":[0.095,0.425,0.84,0.095],"c":[0.053,0.3792,0.924,0.1867],"r":6.5988,"img":"img/U9/walk/p008_22_04.jpg","say":"수평적인 경사지붕, 벽돌이나 목재 같은 단순한 재료."},{"b":[0.19,0.54,0.195,0.45],"c":[0.178,0.505,0.219,0.495],"r":0.5899,"img":"img/U9/walk/p008_22_05.jpg","say":"왼쪽 사진: 기하학 무늬의 색유리 창이에요(캡션 없음)."},{"b":[0.405,0.54,0.495,0.445],"c":[0.3803,0.5105,0.5445,0.4895],"r":1.4831,"img":"img/U9/walk/p008_22_06.jpg","say":"오른쪽 사진: 등받이 높은 의자가 둘러싼 식당이에요(캡션 없음)."}]}},{"p":9,"title":"유니티 교회, 미국 일리노이, 1907","terms":["유니티 교회","두 핵으로 구분된 공간","Functionalism","De Stijl","Frank Lloyd Wright"],"pass1":[{"kind":"analogy","head":"교회를 둘로 쪼개다","scene":"집 한 채를 '예배하는 쪽' 과 '그 밖의 일을 하는 쪽' 으로 나누고 현관으로 이었다고 생각해 보세요.","map":[["예배하는 쪽","종교 부분"],["그 밖의 일을 하는 쪽","비종교적 기능"],["둘을 잇는 현관","입구부"]]},{"kind":"say","lines":["**유니티 교회** 의 실내 사진이에요. 천장이 네모 칸으로 나뉘어 있어요.","1907년, 미국 일리노이예요. **로비 하우스(Robie House)**(1908)보다 한 해 먼저예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**두 핵으로 구분된 공간**: 교회를 두 덩어리로 나눈 배치예요. 정신과 물질, 신과 현세의 대비예요.","**기능주의(Functionalism)**: 사용과 기능을 형태가 드러내는 건축이에요. 이 쪽에서는 '종교와 비종교 기능의 분리' 를 이렇게 불렀어요.","**데 스테일(De Stijl)**: 4단원의 직선과 면의 네덜란드 운동이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**프랭크 로이드 라이트(Frank Lloyd Wright)**, **유니티 교회**, 미국 일리노이, 1907.","건물을 둘로 나누고 이들을 입구부로 연결하는 배치개념.","콘크리트 자체를 외벽 재료로 사용.","**기능주의(Functionalism)**: 종교 부분과 비종교적 기능을 분리.","신의 공간이 아니라 신자들의 공간으로 디자인.","**두 핵으로 구분된 공간**: 정신과 물질의 대비, 신과 현세의 대비.","실내의 선적, 기하학적 장식 → **데 스테일(De Stijl)** 에 영향을 미침."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유니티 교회** 의 실내 장식이 영향을 미친 운동은 무엇일까요?","choices":["**아르 누보(Art Nouveau)**","**데 스테일(De Stijl)**","**유겐트슈틸(Jugendstil)**"],"a":1,"why":"실내의 선적, 기하학적 장식이 데 스테일에 영향을 미쳤어요."},{"kind":"check","q":"**유니티 교회** 의 외벽 재료로 옳은 것은 무엇일까요?","choices":["콘크리트 자체","붉은 벽돌","회반죽 흰 벽과 짙은 나무 프레임"],"a":0,"why":"콘크리트 자체를 외벽 재료로 썼어요. 흰 벽과 나무 프레임은 윌리츠 하우스예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드가 여기서 '**기능주의(Functionalism)**' 라는 말을 써요. 종교와 비종교 기능을 나눴다는 뜻이에요.","그렇다고 라이트를 기능주의 건축가로 외우면 안 돼요. 라이트는 **유기적 건축(Organic Architecture)** 쪽이에요.","'신의 공간' 이 아니라 '신자들의 공간' 이에요. 거꾸로 묻는 O/X 에 조심해요."]},{"kind":"english","head":"논술 답안: 유니티 교회","en":"유니티 교회(1907)는 건물을 둘로 나누어 입구부로 연결하고 콘크리트 자체를 외벽 재료로 사용하였으며, 신자들의 공간으로 디자인되었고 실내 장식은 데 스테일에 영향을 미쳤다.","ko":"배치, 재료, 신자들의 공간, 데 스테일 네 가지예요.","tip":"'둘로, 콘크리트, 신자, 데 스테일' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.065,0.045,0.51,0.88],"c":[0.0395,0.001,0.561,0.968],"r":0.7727,"img":"img/U9/walk/p009_22_01.jpg","say":"실내 사진: 네모 칸 천창, 세로 막대가 늘어선 벽, 직선 장식."},{"b":[0.135,0.94,0.43,0.035],"c":[0.1135,0.89,0.473,0.11],"r":5.7333,"img":"img/U9/walk/p009_22_02.jpg","say":"캡션: 프랭크 로이드 라이트, 유니티 교회, 미국 일리노이, 1907."},{"b":[0.62,0.1,0.115,0.04],"c":[0.5775,0.065,0.2,0.11],"r":2.4242,"img":"img/U9/walk/p009_22_03.jpg","say":"제목: 유니티 교회."},{"b":[0.615,0.165,0.345,0.215],"c":[0.5978,0.149,0.3795,0.247],"r":2.0486,"img":"img/U9/walk/p009_22_04.jpg","say":"둘로 나누고 입구부로 연결, 콘크리트를 외벽 재료로."},{"b":[0.615,0.39,0.345,0.215],"c":[0.5978,0.374,0.3795,0.247],"r":2.0486,"img":"img/U9/walk/p009_22_05.jpg","say":"기능주의(종교, 비종교 분리), 신자들의 공간."},{"b":[0.615,0.62,0.345,0.22],"c":[0.5978,0.604,0.3795,0.252],"r":2.0079,"img":"img/U9/walk/p009_22_06.jpg","say":"두 핵으로 구분된 공간, 선적이고 기하학적인 장식 → 데 스테일에 영향."}]}},{"p":10,"title":"유니티 교회의 실내와 평면","terms":["유니티 교회","천창","갤러리층","두 핵으로 구분된 공간"],"pass1":[{"kind":"say","lines":["왼쪽은 **유니티 교회** 실내, 오른쪽은 평면도예요.","평면을 보면 건물이 왼쪽과 오른쪽 두 덩어리로 나뉘어 있어요.","천장 가운데로 하늘빛이 들어오는 **천창** 이 있어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**천창**: 천장이나 지붕에 낸 하늘 쪽 창이에요.","**갤러리층**: 큰 실내를 빙 둘러 위쪽에 낸 발코니 같은 층이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["실내 십자의 중앙에 **천창** 설치.","3층 높이의 내부공간은 중2층 및 사각형 평면의 3변을 둘러싼 **갤러리층** 구성.","레벨의 조정으로 친밀한 공간 형성: 청중은 설교하는 사람보다 낮거나 높은 위치로 느껴지지 않음.","실내의 단순한 장식은 허례허식과 의식에 얽매이지 않음.","장식은 작게 분할된 판자를 사용."]},{"kind":"points","head":"평면 이름표 읽기","items":["왼쪽 덩어리 UNITY TEMPLE: PULPIT(설교단), CHOIR(성가대), BALCONY(발코니).","오른쪽 덩어리 UNITY HOUSE: SEWING ROOM, KITCHEN, STORAGE.","가운데 ENTRANCE HALL, ENTRANCE COURT, PASTOR'S STUDY 가 둘을 이어요. 이것이 **두 핵으로 구분된 공간** 이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유니티 교회** 의 **갤러리층** 은 사각형 평면의 몇 변을 둘러쌀까요?","choices":["2변","3변","4변"],"a":1,"why":"3층 높이의 내부공간, 사각형 평면의 3변을 둘러싼 갤러리층이에요. 3이 두 번 나와요."},{"kind":"check","q":"**유니티 교회** 에서 레벨을 조정한 목적으로 옳은 것은 무엇일까요?","choices":["청중이 설교자보다 낮거나 높다고 느끼지 않게 하려고","작품보다 관람객을 전시하려고","세 방향의 전망을 주려고"],"a":0,"why":"레벨의 조정으로 친밀한 공간을 형성했어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**천창** 은 9단원에 세 번 나와요. 유니티 교회(실내 십자의 중앙), 존슨 왁스 본부, 구겐하임(천창 돔).","유니티 교회의 장식은 '작게 분할된 판자' 예요. 재료를 묻는 문제에 조심해요."]}],"walk":{"head":null,"parts":[{"b":[0.02,0.12,0.4,0.41],"c":[0,0.0995,0.44,0.451],"r":1.3008,"img":"img/U9/walk/p010_23_01.jpg","say":"실내 사진: 천장의 네모 칸에서 빛이 들어오고, 양옆 위에 갤러리층이 있어요."},{"b":[0.51,0.17,0.2,0.3],"c":[0.498,0.154,0.224,0.332],"r":0.8996,"img":"img/U9/walk/p010_23_02.jpg","say":"평면 왼쪽: UNITY TEMPLE. 설교단(PULPIT)과 BALCONY."},{"b":[0.715,0.27,0.085,0.18],"c":[0.6575,0.254,0.2,0.212],"r":1.2579,"img":"img/U9/walk/p010_23_03.jpg","say":"가운데: ENTRANCE HALL. 두 덩어리를 잇는 입구부예요."},{"b":[0.79,0.13,0.17,0.4],"c":[0.775,0.11,0.2,0.44],"r":0.6061,"img":"img/U9/walk/p010_23_04.jpg","say":"평면 오른쪽: UNITY HOUSE. SEWING ROOM, KITCHEN."},{"b":[0.07,0.57,0.79,0.11],"c":[0.0305,0.5372,0.869,0.1756],"r":6.5983,"img":"img/U9/walk/p010_23_05.jpg","say":"천창은 실내 십자의 중앙, 3층 높이 공간과 3변의 갤러리층."},{"b":[0.07,0.695,0.88,0.22],"c":[0.026,0.679,0.968,0.252],"r":5.1217,"img":"img/U9/walk/p010_23_06.jpg","say":"레벨 조정으로 친밀한 공간, 단순한 장식, 작게 분할된 판자."}]}},{"p":11,"title":"탤리에신(Taliesin), 스프링 그린, 위스콘신, 1929","terms":["Taliesin","개방형 벽난로","Frank Lloyd Wright"],"pass1":[{"kind":"say","lines":["언덕을 배경으로 낮게 앉은 집과 실내 사진 두 장이에요.","**탤리에신(Taliesin)** 은 웨일스어로 '빛나는 언덕' 이라는 뜻이에요.","이름처럼 언덕 위에 낮게 엎드려 자연과 어울리는 집이에요."]}],"pass2":[{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**탤리에신(Taliesin)**: 웨일스어로 빛나는 언덕을 의미.","저층의 단층 건물이 언덕 위에 위치하여 자연과 조화.","경사진 천장 면들과 벽들과 커다란 돌들을 쌓아 만든 벽난로 공간을 가지고 있는 거실.","캡션: **프랭크 로이드 라이트(Frank Lloyd Wright)**, 탤리에신, 스프링 그린, 위스콘신, 1929."]},{"kind":"points","head":"앞 쪽과 이어 보기","items":["p.8 에서 벽난로는 '주택 전체의 절정이자 중심' 이었어요.","탤리에신 거실에도 큰 돌을 쌓은 벽난로 공간이 있어요. 같은 생각이 이어져요.","라이트가 태어난 곳도 위스콘신이에요(p.2)."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**탤리에신(Taliesin)** 이라는 이름의 뜻으로 옳은 것은 무엇일까요?","choices":["웨일스어로 빛나는 언덕","독일어로 대초원의 집","핀란드어로 숲속의 집"],"a":0,"why":"웨일스어로 빛나는 언덕이라는 뜻이에요."},{"kind":"check","q":"슬라이드 캡션에 적힌 **탤리에신(Taliesin)** 의 장소와 연도는 무엇일까요?","choices":["미국 일리노이, 1907","스프링 그린, 위스콘신, 1929","미국 펜실베니아, 1939"],"a":1,"why":"스프링 그린, 위스콘신, 1929예요. 일리노이 1907은 유니티 교회, 펜실베니아 1939는 낙수장이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["시험에는 슬라이드 캡션 '스프링 그린, 위스콘신, 1929' 를 그대로 써요.","바깥 사진은 사막 같은 풍경이라 캡션과 다른 곳일 수도 있어요. 슬라이드만으로는 확정할 수 없어요."]}],"walk":{"head":{"b":[0.0424,0.046,0.0877,0.0511],"c":[0,0.03,0.2,0.0831],"r":3.209,"img":"img/U9/walk/p011_h.jpg"},"parts":[{"b":[0.03,0.11,0.55,0.11],"c":[0.0025,0.094,0.605,0.142],"r":5.6808,"img":"img/U9/walk/p011_22_01.jpg","say":"Taliesin: 웨일스어로 빛나는 언덕. 저층 단층 건물이 언덕 위에서 자연과 조화."},{"b":[0.03,0.235,0.6,0.095],"c":[0.0,0.2158,0.66,0.1333],"r":6.6017,"img":"img/U9/walk/p011_22_02.jpg","say":"경사진 천장, 큰 돌들을 쌓아 만든 벽난로 공간이 있는 거실."},{"b":[0.03,0.52,0.475,0.345],"c":[0.0062,0.5028,0.5225,0.3795],"r":1.8357,"img":"img/U9/walk/p011_22_03.jpg","say":"외관 사진: 언덕 앞에 낮은 건물, 돌 벽과 붉은 계단, 앞에 물이 있어요."},{"b":[0.05,0.895,0.43,0.08],"c":[0.0285,0.879,0.473,0.112],"r":5.631,"img":"img/U9/walk/p011_22_04.jpg","say":"캡션: 프랭크 로이드 라이트, 탤리에신, 스프링 그린, 위스콘신, 1929."},{"b":[0.59,0.295,0.355,0.365],"c":[0.5722,0.2767,0.3905,0.4015],"r":1.2968,"img":"img/U9/walk/p011_22_05.jpg","say":"오른쪽 위: 경사진 나무 천장 아래 돌을 쌓은 벽난로."},{"b":[0.53,0.685,0.45,0.3],"c":[0.505,0.668,0.495,0.332],"r":1.988,"img":"img/U9/walk/p011_22_06.jpg","say":"오른쪽 아래: 돌벽과 경사진 천장의 넓은 거실."}]}},{"p":12,"title":"낙수장(Falling Water, House Kaufmann)","terms":["Falling Water, House Kaufmann","캔틸레버","상호관입","Organic Architecture","Frank Lloyd Wright"],"pass1":[{"kind":"analogy","head":"바위 위의 쟁반들","scene":"바위 위에 쟁반 여러 장을 한쪽 끝만 걸쳐 겹쳐 놓은 모습을 떠올려 보세요.","map":[["한쪽만 붙잡은 쟁반","**캔틸레버**"],["숲과 바위","자연"],["쟁반과 바위가 한 풍경","**유기적 건축(Organic Architecture)**"]]},{"kind":"say","lines":["숲속에 납작한 판들이 층층이 튀어나온 집, **낙수장(Falling Water, House Kaufmann)** 이에요.","**프랭크 로이드 라이트(Frank Lloyd Wright)** 의 유기적 주거건축의 결정체예요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**낙수장(Falling Water, House Kaufmann)**: 폭포 위에 캔틸레버 테라스를 겹쳐 띄운 주택이에요.","**캔틸레버**: 한쪽 끝만 붙잡고 허공으로 쭉 내민 수평 구조예요.","**상호관입**: 공간과 공간이 서로 파고들어 겹치는 것이에요(p.8)."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["라이트의 유기적 주거건축의 결정체.","자연과의 유기적 교감.","내부, 외부의 **상호관입**. 내부공간의 **상호관입**.","수평적 요소(**캔틸레버**)의 사용: 미국의 광활한 대지와 조화.","유기적으로 해석한 개방공간.","평면 이름표: STONE PAVED TERRACE(돌을 깐 테라스), CONCRETE TRELLIS(콘크리트 격자 시렁)."]},{"kind":"bg","src":"일반 상식","lines":["캔틸레버는 선반 받침 없이 벽에서 튀어나온 책상판 같은 구조예요.","한쪽 끝만 고정되어 있어서, 아래가 비어 보이고 떠 있는 느낌을 줘요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**낙수장(Falling Water, House Kaufmann)** 에서 미국의 광활한 대지와 조화를 이루는 수평적 요소는 무엇일까요?","choices":["**캔틸레버**","**접시형 요소**","**갤러리층**"],"a":0,"why":"수평적 요소(캔틸레버)의 사용이에요."},{"kind":"check","q":"**낙수장(Falling Water, House Kaufmann)** 을 설명한 슬라이드 문구로 옳은 것은 무엇일까요?","choices":["라이트의 유기적 주거건축의 결정체","모든 모던 빌딩들 중 가장 뛰어난 디자인","상자 형태를 파괴했다"],"a":0,"why":"결정체예요. 두 번째는 구겐하임 미술관, 세 번째는 윌리츠 하우스 문구예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["같은 작품의 이름이 셋이에요. 낙수장 = Falling Water = House Kaufmann.","**상호관입** 이 두 번 나와요. '내부, 외부의 상호관입' 과 '내부공간의 상호관입' 을 둘 다 써요."]}],"walk":{"head":null,"parts":[{"b":[0.07,0.05,0.385,0.04],"c":[0.0508,0.015,0.4235,0.11],"r":5.1333,"img":"img/U9/walk/p012_23_01.jpg","say":"제목: 낙수장(Falling Water, House Kaufmann)."},{"b":[0.09,0.1,0.38,0.11],"c":[0.071,0.084,0.418,0.142],"r":3.9249,"img":"img/U9/walk/p012_23_02.jpg","say":"유기적 주거건축의 결정체, 자연과의 유기적 교감."},{"b":[0.09,0.22,0.27,0.11],"c":[0.0765,0.204,0.297,0.142],"r":2.7887,"img":"img/U9/walk/p012_23_03.jpg","say":"내부, 외부의 상호관입과 내부공간의 상호관입."},{"b":[0.09,0.34,0.42,0.17],"c":[0.069,0.324,0.462,0.202],"r":3.0495,"img":"img/U9/walk/p012_23_04.jpg","say":"수평적 요소(캔틸레버), 미국의 광활한 대지와 조화, 개방공간."},{"b":[0.015,0.54,0.48,0.43],"c":[0,0.5185,0.528,0.473],"r":1.4884,"img":"img/U9/walk/p012_23_05.jpg","say":"평면도: STONE PAVED TERRACE 와 CONCRETE TRELLIS 이름표."},{"b":[0.515,0.2,0.475,0.78],"c":[0.4775,0.142,0.5225,0.858],"r":0.812,"img":"img/U9/walk/p012_23_06.jpg","say":"숲속 사진: 노란 판들이 층층이 수평으로 튀어나와요."}]}},{"p":13,"title":"낙수장: 라이트의 말과 땅의 혼(Genius Loci), 미국 펜실베니아, 1939","terms":["Falling Water, House Kaufmann","Genius Loci","대지의 퇴적 지질","테라스"],"pass1":[{"kind":"say","lines":["폭포 위에 집이 걸쳐 있는 가을 사진이에요.","**낙수장(Falling Water, House Kaufmann)** 은 집이 자연을 가리지 않고 오히려 돋보이게 해요.","그 장소만의 성격, **땅의 혼(Genius Loci)** 을 살렸기 때문이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**땅의 혼(Genius Loci)**: 그 장소만이 가진 고유한 성격이에요.","**대지의 퇴적 지질**: 땅에 켜켜이 쌓인 바위층의 결이에요."]},{"kind":"points","head":"라이트의 말 두 개","items":["\"숲, 강, 바위 및 구조 요소의 조합에 의해 생성된 위대한 고요함\"","\"자연적인 수단과 기술적인 수단은 조화를 이루어야 한다.\""]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["건물로 인해 자연의 웅장함이 강조되고 통합되고, 이는 일상 생활의 필수적인 부분이 됨.","**테라스** 바닥은 세 방향의 전망을 제공. 모든 수직 요소는 석재로 마감.","자연 경관의 연장. 긴장되고 질서잡힌 형태와 자연의 조화.","디자인에 **대지의 퇴적 지질** 반영.","**땅의 혼(Genius Loci)** 에 부응, 장소에 대한 관심.","캡션: 프랭크 L. 라이트, 미국 펜실베니아, 1939."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**낙수장(Falling Water, House Kaufmann)** 의 **테라스** 바닥이 제공하는 것은 무엇일까요?","choices":["두 방향의 전망","세 방향의 전망","상부 채광"],"a":1,"why":"테라스 바닥은 세 방향의 전망을 제공해요."},{"kind":"check","q":"**낙수장(Falling Water, House Kaufmann)** 의 모든 수직 요소는 무엇으로 마감했을까요?","choices":["석재","회반죽","노출 콘크리트"],"a":0,"why":"모든 수직 요소는 석재로 마감했어요. 대지의 퇴적 지질을 반영한 거예요."},{"kind":"check","q":"'**땅의 혼(Genius Loci)** 에 부응' 과 짝을 이루는 말은 무엇일까요?","choices":["장소에 대한 관심","작품보다 관람객을 전시","보편해보다 특수해"],"a":0,"why":"땅의 혼에 부응, 장소에 대한 관심이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["이 쪽 캡션에는 작품 이름이 빠져 있어요. 낙수장 쪽이라는 것은 앞 쪽(p.12)에서 알 수 있어요.","슬라이드 표기는 '펜실베니아' 예요. 답안에는 이 표기를 따라요.","1939는 낙수장과 존슨 왁스 본부(p.18)가 같은 해예요."]},{"kind":"english","head":"논술 답안: 낙수장","en":"낙수장(1939)은 라이트의 유기적 주거건축의 결정체로, 캔틸레버를 사용해 미국의 광활한 대지와 조화를 이루고 대지의 퇴적 지질을 반영하여 땅의 혼(Genius Loci)에 부응하였다.","ko":"결정체, 캔틸레버, 퇴적 지질, 땅의 혼 네 가지예요.","tip":"'결정체, 쟁반(캔틸레버), 바위층, 땅의 혼' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.085,0.68,0.17],"c":[0.016,0.069,0.748,0.202],"r":4.9373,"img":"img/U9/walk/p013_23_01.jpg","say":"위: 라이트의 말 두 개. 위대한 고요함, 자연적 수단과 기술적 수단의 조화."},{"b":[0.04,0.335,0.69,0.095],"c":[0.0055,0.3058,0.759,0.1533],"r":6.6014,"img":"img/U9/walk/p013_23_02.jpg","say":"자연의 웅장함이 강조되고 일상 생활의 필수적인 부분이 돼요."},{"b":[0.04,0.445,0.44,0.285],"c":[0.018,0.429,0.484,0.317],"r":2.0358,"img":"img/U9/walk/p013_23_03.jpg","say":"테라스 세 방향 전망, 수직 요소는 석재, 자연 경관의 연장, 퇴적 지질 반영."},{"b":[0.018,0.77,0.408,0.12],"c":[0,0.754,0.4488,0.152],"r":3.9368,"img":"img/U9/walk/p013_23_04.jpg","say":"네모 상자: 땅의 혼(Genius Loci)에 부응, 장소에 대한 관심."},{"b":[0.135,0.94,0.31,0.04],"c":[0.1195,0.89,0.341,0.11],"r":4.1333,"img":"img/U9/walk/p013_23_05.jpg","say":"캡션: 프랭크 L. 라이트, 미국 펜실베니아, 1939. 작품 이름은 빠져 있어요."},{"b":[0.483,0.395,0.505,0.59],"c":[0.4445,0.351,0.5555,0.649],"r":1.1412,"img":"img/U9/walk/p013_23_06.jpg","say":"사진: 폭포 위로 수평 판들이 튀어나온 가을의 낙수장."}]}},{"p":14,"title":"낙수장 사진 두 장 (여름, 겨울)","terms":["Falling Water, House Kaufmann","캔틸레버","Genius Loci"],"pass1":[{"kind":"say","lines":["글자 없이 **낙수장(Falling Water, House Kaufmann)** 사진만 두 장이에요.","왼쪽은 초록 숲의 여름, 오른쪽은 눈 덮인 겨울 저녁이에요.","계절이 바뀌어도 집이 폭포와 바위의 일부처럼 보여요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽: 폭포 바로 위로 밝은 색 판들이 층층이 튀어나와 있어요. **캔틸레버** 예요.","왼쪽: 판들 뒤로 돌을 쌓은 세로 벽이 솟아 있어요. 수직 요소는 석재 마감이에요(p.13).","오른쪽: 창마다 불이 켜져 있고, 아래로 눈 덮인 바위와 폭포가 흘러요.","두 장 모두 집이 자연을 가리지 않고 풍경의 연장처럼 보여요. **땅의 혼(Genius Loci)** 에 부응한 모습이에요."]},{"kind":"look","walked":1}],"pass3":[],"walk":{"head":null,"parts":[{"b":[0.01,0.105,0.47,0.795],"c":[0,0.0653,0.517,0.8745],"r":0.7883,"img":"img/U9/walk/p014_21_01.jpg","say":"왼쪽: 여름 숲 속, 폭포 위로 수평 판들이 튀어나오고 돌 벽이 솟아요."},{"b":[0.5,0.105,0.465,0.785],"c":[0.4768,0.0657,0.5115,0.8635],"r":0.7898,"img":"img/U9/walk/p014_21_02.jpg","say":"오른쪽: 눈 덮인 겨울, 불 켜진 창과 아래로 흐르는 폭포."}]}},{"p":15,"title":"낙수장의 실내","terms":["Falling Water, House Kaufmann","개방형 벽난로","수평 띠"],"pass1":[{"kind":"say","lines":["**낙수장(Falling Water, House Kaufmann)** 의 거실 사진 두 장이에요.","넓은 창 너머로 숲이 보이고, 바닥과 벽난로가 돌로 되어 있어요.","바깥의 바위가 거실 안까지 들어온 느낌이에요."]}],"pass2":[{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["커다랗고 트인 거실 공간은 창문 너머로 시골 풍경을 내다볼 수 있도록 넓은 유리 부분을 사용.","그 지역의 돌을 이용한 바닥과 벽난로가 있음.","천장의 패턴들은 감추어져 있는 조명 요소들.","붙박이로 처리된 벤치들과 움직일 수 있는 스툴들은 라이트 자신의 디자인.","매끄러운 회벽과 대조를 이루는 거친 돌 마감의 벽과 자연목 요소들, 다채로운 창문 부분들이 연속적인 띠를 이루도록 디자인."]},{"kind":"points","head":"앞 쪽과 이어 보기","items":["벽난로가 집의 중심(p.8), 탤리에신의 돌 벽난로(p.11)와 같은 생각이에요.","창문이 연속적인 띠를 이루는 것은 **로비 하우스(Robie House)** 의 창문 **수평 띠** 와 닮았어요.","직접 디자인한 가구는 **윌리츠 하우스(House Willits)** 에서도 나왔어요(p.4)."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**낙수장(Falling Water, House Kaufmann)** 실내에서 천장의 패턴들은 무엇일까요?","choices":["감추어져 있는 조명 요소들","천창 돔","접시형 요소"],"a":0,"why":"천장의 패턴들은 감추어져 있는 조명 요소들이에요."},{"kind":"check","q":"낙수장 실내의 붙박이 벤치와 움직일 수 있는 스툴은 누구의 디자인일까요?","choices":["**알바 알토(Alvar Aalto)**","**프랭크 로이드 라이트(Frank Lloyd Wright)**","**루이스 설리번(Louis Sullivan)**"],"a":1,"why":"라이트 자신의 디자인이에요."}],"walk":{"head":null,"parts":[{"b":[0.035,0.03,0.88,0.095],"c":[0,0,0.968,0.1956],"r":6.5985,"img":"img/U9/walk/p015_22_01.jpg","say":"넓은 거실, 시골 풍경을 내다보는 넓은 유리 부분."},{"b":[0.035,0.14,0.78,0.165],"c":[0,0.124,0.858,0.197],"r":5.8071,"img":"img/U9/walk/p015_22_02.jpg","say":"지역의 돌로 된 바닥과 벽난로, 천장 패턴 속 감춘 조명, 라이트가 디자인한 벤치와 스툴."},{"b":[0.035,0.32,0.88,0.1],"c":[0,0.2722,0.968,0.1956],"r":6.5985,"img":"img/U9/walk/p015_22_03.jpg","say":"매끄러운 회벽과 거친 돌 벽, 자연목, 창문의 연속적인 띠."},{"b":[0.07,0.465,0.405,0.51],"c":[0.0498,0.439,0.4455,0.561],"r":1.0588,"img":"img/U9/walk/p015_22_04.jpg","say":"왼쪽 사진: 천장에서 빛이 나오는 넓은 거실, 낮은 소파와 돌 기둥."},{"b":[0.505,0.465,0.48,0.51],"c":[0.472,0.439,0.528,0.561],"r":1.2549,"img":"img/U9/walk/p015_22_05.jpg","say":"오른쪽 사진: 돌을 쌓은 벽난로와 바닥에 솟은 바위, 붉은 둥근 주전자."}]}},{"p":16,"title":"유기적 건축이란(Organic Architecture)?","terms":["Organic Architecture","internationale Architektur","Human Scale","Art Nouveau","Frank Lloyd Wright","Alvar Aalto"],"pass1":[{"kind":"analogy","head":"나무처럼 자라는 건물","scene":"나무는 땅에서 자라서 주변 풍경과 한 몸이 돼요. 건물도 그렇게 만들자는 생각이에요.","map":[["땅에서 자라는 나무","**유기적 건축(Organic Architecture)**"],["어디에나 똑같이 찍어 낸 상자","**국제주의 건축(internationale Architektur)**"],["사람 몸에 맞춘 크기","**인간적 척도(Human Scale)**"]]},{"kind":"say","lines":["그래서 **유기적 건축(Organic Architecture)** 은 국제주의 건축과 대립되는 개념이에요.","주문으로 보면, 기계 시대에 라이트는 '자연과 한 몸' 이라고 대답한 셈이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**유기적 건축(Organic Architecture)**: 주변 자연과 한 몸이 되는 건축이에요.","**국제주의 건축(internationale Architektur)**: 4단원, 나라가 달라도 건물이 닮는 흐름이에요.","**인간적 척도(Human Scale)**: 사람 몸 크기에 맞춘 크기 감각이에요.","Hierarchy: 위계, 즉 큰 것과 작은 것의 질서예요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["건축가: Gaudi, Wright, **아르 누보(Art Nouveau)** 건축가, Aalto 등.","**국제주의 건축(internationale Architektur)** 과 대립되는 개념.","외관은 친근한 재료 사용. 형태에서 자연의 곡선 사용.","건물의 형태나 내부공간에 자연물을 이미지화. 건물을 주변의 자연과 융합시킴.","구조적 시스템적 규칙보다 풍부함과 변화 추구.","**인간적 척도(Human Scale)**. 유기생명체의 시스템과 같은 Hierarchy 형성."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유기적 건축(Organic Architecture)** 과 대립되는 개념으로 슬라이드에 적힌 것은 무엇일까요?","choices":["**아르 누보(Art Nouveau)**","**국제주의 건축(internationale Architektur)**","자연주의적 경향"],"a":1,"why":"국제주의 건축과 대립되는 개념이에요. 아르누보 건축가는 오히려 유기적 건축 쪽에 들어가요."},{"kind":"check","q":"다음 중 슬라이드의 **유기적 건축(Organic Architecture)** 건축가 목록에 없는 사람은 누구일까요?","choices":["Gaudi","Wright","Aalto","Sullivan"],"a":3,"why":"목록은 Gaudi, Wright, Art Nouveau 건축가, Aalto 등이에요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["슬라이드의 '풍부한과 변화 추구' 는 '풍부함과' 의 오타로 보여요.","Human Scale 은 알토 쪽(p.22)에서 '인간적 척도' 로 다시 나와요. 같은 말이에요.","아래 사진들에는 캡션이 없어요. 작품 이름을 지어 쓰지 말고 '곡선 장식' 으로만 기억해요."]},{"kind":"english","head":"논술 답안: 유기적 건축","en":"유기적 건축은 국제주의 건축과 대립되는 개념으로, 친근한 재료와 자연의 곡선을 사용하고 건물을 주변의 자연과 융합시키며 Human Scale 과 유기생명체 같은 Hierarchy 를 형성한다.","ko":"정의(대립 개념), 재료, 곡선, 자연 융합, Human Scale, Hierarchy 순서예요. 건축가 이름(Gaudi, Wright, Aalto)을 붙이면 더 좋아요.","tip":"'국제주의 반대, 재료, 곡선, 융합, 사람 크기, 위계' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.045,0.035,0.43,0.045],"c":[0.0235,0.0025,0.473,0.11],"r":5.7333,"img":"img/U9/walk/p016_22_01.jpg","say":"제목: 유기적 건축이란(Organic Architecture)?"},{"b":[0.06,0.1,0.5,0.1],"c":[0.035,0.084,0.55,0.132],"r":5.5556,"img":"img/U9/walk/p016_22_02.jpg","say":"Gaudi, Wright, Art Nouveau 건축가, Aalto 등. 국제주의 건축과 대립."},{"b":[0.11,0.22,0.49,0.42],"c":[0.0855,0.199,0.539,0.462],"r":1.5556,"img":"img/U9/walk/p016_22_03.jpg","say":"특징 일곱 줄: 친근한 재료, 자연의 곡선, 자연물 이미지화, 융합, 변화, Human Scale, Hierarchy."},{"b":[0.012,0.655,0.47,0.345],"c":[0,0.6205,0.517,0.3795],"r":1.8164,"img":"img/U9/walk/p016_22_04.jpg","say":"왼쪽 아래 사진 두 장: 뼈 같은 곡선 발코니, 비늘 같은 지붕과 둥근 탑(캡션 없음)."},{"b":[0.7,0.018,0.288,0.48],"c":[0.6832,0,0.3168,0.528],"r":0.8,"img":"img/U9/walk/p016_22_05.jpg","say":"오른쪽 위: 덩굴 같은 금속 곡선이 감싼 계단 홀(캡션 없음)."},{"b":[0.7,0.528,0.288,0.47],"c":[0.6832,0.483,0.3168,0.517],"r":0.817,"img":"img/U9/walk/p016_22_06.jpg","say":"오른쪽 아래: 곡선 철 장식과 유리 천장의 계단 실내(캡션 없음)."}]}},{"p":17,"title":"전일적 세계관과 유기적 디자인","terms":["전일적 세계관","기계론적 세계관","유기론적 세계관","Art Nouveau","Jugendstil","Organic Architecture"],"pass1":[{"kind":"compare","head":"세상을 보는 두 눈","cols":["관점","세상을 무엇처럼 보나","건축으로 나오면"],"rows":[["**기계론적 세계관**","부품이 맞물린 기계","기계를 본보기로 짓기"],["**유기론적 세계관**","살아 있는 생명체","자연을 본보기로(자연이 원형)"]]},{"kind":"say","lines":["**유기적 건축(Organic Architecture)** 의 뿌리는 '세상을 하나의 생명으로 보는 눈' 이에요.","2단원의 **아르 누보(Art Nouveau)** 곡선이 여기서 다시 살아나요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**전일적 세계관**: 세상을 하나로 이어진 전체로 보는 관점이에요.","**기계론적 세계관**: 세상을 부품이 맞물린 기계처럼 보는 관점이에요.","**유기론적 세계관**: 세상을 살아 있는 생명체처럼 보는 관점이에요."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["**기계론적 세계관** 에 기초한 공간구축의 흐름과는 달리, **유기론적 세계관** 을 바탕으로 하는 흐름이 있어요.","1890년대부터 1910년대까지 **아르 누보(Art Nouveau)**, **유겐트슈틸(Jugendstil)** 등에서의 자연주의적 경향으로 나타났어요.","즉 자연이 모든 구축 형태의 원형이라는 개념이에요."]},{"kind":"points","head":"개념의 확장","items":["자연을 신비적이고 원초적인 힘의 상징으로 바라본다.","구축물을 자연경관의 구성요소로 인식하여 인공환경과 그것을 에워싸는 토양 및 풍토와의 유기적 연계를 추구한다.","문화적 전통과의 맥락을 의식한다."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**유기론적 세계관** 을 바탕으로 한 흐름이 자연주의적 경향으로 나타난 시기와 사조로 옳은 것은 무엇일까요?","choices":["1890-1910년대, **아르 누보(Art Nouveau)** 와 **유겐트슈틸(Jugendstil)**","1920-30년대, 표현주의와 암스테르담파","1932년 이후, 국제주의 양식"],"a":0,"why":"1890년대부터 1910년대까지 아르누보, 유겐트슈틸 등의 자연주의적 경향이에요."},{"kind":"check","q":"이 쪽의 '개념의 확장' 에 들어가지 않는 것은 무엇일까요?","choices":["자연을 신비적이고 원초적인 힘의 상징으로 본다","토양 및 풍토와의 유기적 연계를 추구한다","자연과 대립하는 기계미학을 근본으로 삼는다","문화적 전통과의 맥락을 의식한다"],"a":2,"why":"기계미학을 근본으로 삼는 것은 4단원 데 스테일 선언이에요. 유기적 디자인과 반대예요."},{"kind":"english","head":"논술 답안: 전일적 세계관","en":"기계론적 세계관에 기초한 공간구축의 흐름과 달리 유기론적 세계관을 바탕으로 한 흐름이 1890-1910년대 아르누보, 유겐트슈틸의 자연주의적 경향으로 나타났으며, 자연이 모든 구축 형태의 원형이라는 개념이다.","ko":"기계론과 유기론의 대비, 시기, 사조, '자연이 원형' 네 덩어리예요.","tip":"'기계 말고 생명, 1890-1910, 아르누보, 자연이 원형' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.24,0.35,0.045],"c":[0.0225,0.2075,0.385,0.11],"r":4.6667,"img":"img/U9/walk/p017_23_01.jpg","say":"제목: 전일적 세계관과 유기적 디자인."},{"b":[0.06,0.295,0.88,0.155],"c":[0.016,0.2747,0.968,0.1956],"r":6.5985,"img":"img/U9/walk/p017_23_02.jpg","say":"기계론적 세계관과 다른 유기론적 세계관, 1890-1910년대 아르누보, 유겐트슈틸, 자연이 원형."},{"b":[0.06,0.53,0.6,0.1],"c":[0.03,0.5133,0.66,0.1333],"r":6.6017,"img":"img/U9/walk/p017_23_03.jpg","say":"개념의 확장 1: 자연을 신비적이고 원초적인 힘의 상징으로."},{"b":[0.06,0.645,0.89,0.1],"c":[0.0155,0.5961,0.979,0.1978],"r":6.5993,"img":"img/U9/walk/p017_23_04.jpg","say":"개념의 확장 2: 토양 및 풍토와의 유기적 연계."},{"b":[0.06,0.755,0.4,0.05],"c":[0.04,0.725,0.44,0.11],"r":5.3333,"img":"img/U9/walk/p017_23_05.jpg","say":"개념의 확장 3: 문화적 전통과의 맥락."}]}},{"p":18,"title":"존슨 왁스 본부(S.C. Johnson Wax Headquarters), 미국 위스콘신 라신, 1939","terms":["S.C. Johnson Wax Headquarters","great room","접시형 요소","천창","Frank Lloyd Wright"],"pass1":[{"kind":"analogy","head":"연잎 연못","scene":"연잎이 물 위에 가득 떠 있고, 그 틈으로 햇빛이 새어 드는 연못 바닥을 떠올려 보세요.","map":[["가는 연잎 줄기","콘크리트 기둥"],["둥근 연잎","**접시형 요소**"],["연잎 틈으로 드는 햇빛","원 모양들 사이의 **천창**"]]},{"kind":"say","lines":["**존슨 왁스 본부(S.C. Johnson Wax Headquarters)** 의 큰 업무 공간이에요.","**낙수장(Falling Water, House Kaufmann)** 과 같은 1939년 작품이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**great room**: 존슨 왁스 본부의 크고 탁 트인 업무 공간이에요.","**접시형 요소**: 기둥 꼭대기의 둥근 접시 모양이에요.","**천창**: 천장에 낸 하늘 쪽 창이에요(유니티 교회에서도 나왔어요)."]},{"kind":"points","head":"빠뜨리면 안 되는 사실","items":["S. C. 존슨 왁스 공장에 세워진 행정 업무용 빌딩.","\"**great room**\" 은 콘크리트로 만들어진 구조적 기둥들에 의해 압도적 분위기를 형성.","기둥들은 천장에 있는 **접시형 요소** 들로부터 퍼져 나옴.","콘크리트로 만들어진 원 모양들 사이에 **천창** 배치: 일광을 제공.","캡션: **프랭크 로이드 라이트(Frank Lloyd Wright)**, **존슨 왁스 본부(S.C. Johnson Wax Headquarters)**, 미국 위스콘신 라신, 1939."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**존슨 왁스 본부(S.C. Johnson Wax Headquarters)** 의 장소와 연도로 옳은 것은 무엇일까요?","choices":["미국 위스콘신 라신, 1939","스프링 그린, 위스콘신, 1929","뉴욕, 1959"],"a":0,"why":"위스콘신 라신, 1939예요. 스프링 그린 1929는 탤리에신이에요."},{"kind":"check","q":"**great room** 의 콘크리트 기둥들은 어디에서 퍼져 나올까요?","choices":["천장에 있는 **접시형 요소** 들","돌을 쌓은 벽난로","나선형 램프"],"a":0,"why":"기둥들은 천장에 있는 접시형 요소들로부터 퍼져 나와요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["1939년 라이트 작품은 둘이에요. **낙수장(Falling Water, House Kaufmann)**(펜실베니아)과 존슨 왁스 본부(위스콘신 라신).","**천창** 이 있는 라이트 작품: 유니티 교회(실내 십자의 중앙)와 존슨 왁스 본부(원 모양들 사이)."]},{"kind":"english","head":"논술 답안: 존슨 왁스 본부","en":"존슨 왁스 본부(1939)의 great room 은 천장의 접시형 요소들로부터 퍼져 나온 콘크리트 기둥들이 압도적 분위기를 형성하며, 원 모양들 사이의 천창이 일광을 제공한다.","ko":"great room, 접시형 요소, 기둥, 천창 네 가지예요.","tip":"'연잎(접시) 아래 줄기(기둥), 틈으로 햇빛(천창)' 으로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.045,0.05,0.51,0.14],"c":[0.0195,0.034,0.561,0.172],"r":4.3488,"img":"img/U9/walk/p018_22_01.jpg","say":"제목과 첫 줄: S. C. 존슨 왁스 공장에 세워진 행정 업무용 빌딩."},{"b":[0.045,0.2,0.88,0.1],"c":[0.001,0.1522,0.968,0.1956],"r":6.5985,"img":"img/U9/walk/p018_22_02.jpg","say":"great room: 콘크리트 기둥의 압도적 분위기, 접시형 요소에서 퍼져 나옴."},{"b":[0.045,0.31,0.65,0.05],"c":[0.0125,0.2628,0.715,0.1445],"r":6.5975,"img":"img/U9/walk/p018_22_03.jpg","say":"원 모양들 사이의 천창: 일광을 제공."},{"b":[0.018,0.45,0.515,0.4],"c":[0,0.43,0.5665,0.44],"r":1.7167,"img":"img/U9/walk/p018_22_04.jpg","say":"great room 사진: 가는 흰 기둥 위에 둥근 접시가 펼쳐져요."},{"b":[0.56,0.45,0.405,0.395],"c":[0.5398,0.4302,0.4455,0.4345],"r":1.3671,"img":"img/U9/walk/p018_22_05.jpg","say":"오른쪽 사진: 둥근 상판과 둥근 등받이의 책상과 의자."},{"b":[0.57,0.875,0.4,0.08],"c":[0.55,0.859,0.44,0.112],"r":5.2381,"img":"img/U9/walk/p018_22_06.jpg","say":"캡션: 존슨 왁스 본부(S.C. Johnson Wax Headquarters), 미국 위스콘신 라신, 1939."}]}},{"p":19,"title":"존슨 왁스 본부의 외관, 실내, 평면","terms":["S.C. Johnson Wax Headquarters","Frank Lloyd Wright","great room","접시형 요소","모서리 없는 공간","상부 채광","Falling Water, House Kaufmann"],"pass1":[{"kind":"say","lines":["앞 쪽에 이어서 **존슨 왁스 본부(S.C. Johnson Wax Headquarters)** 예요.","**프랭크 로이드 라이트(Frank Lloyd Wright)** 가 1939년 미국 위스콘신 라신에 지었어요.","벽은 무게를 받지 않아요. 기둥이 숲처럼 서서 건물을 받쳐요.","구석이 둥글게 흐르고, 빛은 옆이 아니라 위에서 들어와요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["하중: 건물이 받는 무게예요. '벽체는 하중을 받지 않음' 은 벽이 무게를 지지 않는다는 뜻이에요.","**모서리 없는 공간**: 각진 구석 없이 둥글게, 자연스럽게 흐르는 내부공간이에요.","**상부 채광**: 옆 창 대신 위에서 빛을 들이는 방법이에요.","추상화: 자연의 모양을 그대로 베끼지 않고 단순한 모양으로 줄이는 것이에요."]},{"kind":"points","head":"슬라이드 다섯 줄","items":["발코니의 띠는 곡면을 이루며 하나의 통일된 전체를 구성해요.","벽체는 하중을 받지 않아요. 고대의 기둥을 형상화한 기둥이 구조 역할을 해요.","**모서리 없는 공간**: 자연스럽게 흐르는 내부공간이에요.","자연 형태를 추상화했어요.","내부 지향의 공간 디자인이에요. 그래서 **상부 채광** 을 써요."]},{"kind":"points","head":"사진과 평면에서 볼 것","items":["왼쪽 위 외관: 벽돌 벽의 모서리가 둥글게 말려 있어요. 가로줄 무늬가 길게 이어져요.","외벽에 옆 창이 거의 보이지 않아요. 빛을 위에서 받는 건물이에요.","오른쪽 위 실내: **great room** 이에요. 가는 기둥 꼭대기가 둥근 **접시형 요소** 로 펼쳐져요.","위층 발코니 띠가 실내를 빙 둘러요. 슬라이드 첫 줄의 '곡면 발코니 띠' 예요.","평면: 동그라미 하나하나가 기둥이에요. Great Workroom 에 격자처럼 줄지어 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**존슨 왁스 본부(S.C. Johnson Wax Headquarters)** 에서 구조 역할을 하는 것은 무엇일까요?","choices":["벽체","고대의 기둥을 형상화한 기둥","유리 커튼월"],"a":1,"why":"벽체는 하중을 받지 않아요. 고대의 기둥을 형상화한 기둥이 구조 역할을 해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["'벽체는 하중을 받지 않음' 은 **존슨 왁스 본부(S.C. Johnson Wax Headquarters)** 의 문장이에요.","같은 1939년에 **낙수장(Falling Water, House Kaufmann)** 도 나왔어요. 둘 다 **프랭크 로이드 라이트(Frank Lloyd Wright)** 예요.","도시로 구분해요. 존슨 왁스는 미국 위스콘신 라신, 낙수장은 미국 펜실베니아예요."]},{"kind":"english","head":"논술 답안: 존슨 왁스 본부","en":"라이트의 존슨 왁스 본부(미국 위스콘신 라신, 1939)는 벽체가 하중을 받지 않고 고대의 기둥을 형상화한 기둥이 구조 역할을 하며, 모서리 없는 공간과 상부 채광으로 자연 형태를 추상화한 내부 지향의 디자인이다.","ko":"구조(기둥) → 공간(모서리 없음) → 빛(상부 채광) 순서예요.","tip":"'기둥, 모서리, 위' 세 단어로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.05,0.46,0.44],"c":[0,0.028,0.506,0.484],"r":1.3939,"img":"img/U9/walk/p019_23_01.jpg","say":"외관: 둥근 모서리의 벽돌 벽이에요. 옆 창이 거의 없어요."},{"b":[0.505,0.05,0.48,0.43],"c":[0.472,0.0285,0.528,0.473],"r":1.4884,"img":"img/U9/walk/p019_23_02.jpg","say":"실내 great room: 접시 머리를 단 기둥이 숲처럼 서 있어요."},{"b":[0.03,0.505,0.44,0.075],"c":[0.008,0.4875,0.484,0.11],"r":5.8667,"img":"img/U9/walk/p019_23_03.jpg","say":"캡션: 프랭크 로이드 라이트, 존슨 왁스 본부, 미국 위스콘신 라신, 1939."},{"b":[0.02,0.615,0.6,0.335],"c":[0,0.5982,0.66,0.3685],"r":2.3881,"img":"img/U9/walk/p019_23_04.jpg","say":"다섯 줄: 곡면 발코니 띠, 하중 안 받는 벽, 모서리 없는 공간, 자연 형태 추상화, 상부 채광."},{"b":[0.63,0.49,0.355,0.49],"c":[0.6095,0.461,0.3905,0.539],"r":0.966,"img":"img/U9/walk/p019_23_05.jpg","say":"평면: 동그라미가 기둥이에요. Great Workroom, Theater, Lobby 이름표가 있어요."}]}},{"p":20,"title":"구겐하임 미술관의 외관, 실내, 단면","terms":["구겐하임 미술관","Frank Lloyd Wright","ramp","rotunda","천창 돔"],"pass1":[{"kind":"say","lines":["이번에는 뉴욕의 **구겐하임 미술관** 이에요. 1959년이에요.","하얀 띠가 빙글빙글 감겨 올라가는 모양이에요.","위로 갈수록 띠가 넓어져요. 거꾸로 세운 깔때기 같아요."]},{"kind":"analogy","head":"달팽이 껍데기 속 미술관","scene":"달팽이 껍데기 안쪽의 빙글빙글 길을 따라 걷는다고 생각해 보세요.","map":[["빙글빙글 감긴 길","나선형 **램프(ramp)**"],["껍데기 가운데의 빈 곳","주 **로툰다(rotunda)** 공간"],["꼭대기로 들어오는 빛","**천창 돔**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**램프(ramp)**: 계단 대신 완만하게 비탈진 통로예요.","**로툰다(rotunda)**: 둥근 원형의 큰 중앙 홀이에요.","**천창 돔**: 꼭대기에서 빛이 들어오는 둥근 지붕이에요.","단면도: 건물을 칼로 자른 면을 옆에서 본 그림이에요. 여기서는 SECTION A-A 예요."]},{"kind":"points","head":"사진과 단면에서 볼 것","items":["설계자, 작품, 도시, 연도는 **프랭크 로이드 라이트(Frank Lloyd Wright)**, **구겐하임 미술관**, 뉴욕, 1959년이에요.","외관: 흰 띠가 층층이 감겨 있고, 위로 갈수록 바깥으로 넓어져요.","아래쪽 벽에 GUGGENHEIM MUSEUM 글자가 붙어 있어요.","실내: 흰 곡선 난간 띠가 이어지고, 그 바깥쪽 벽에 그림이 걸려 있어요.","단면도: 바닥이 비스듬히 겹겹이 올라가고, 꼭대기는 유리 지붕이에요.","1959년은 라이트(1867-1959)의 마지막 해와 같은 숫자예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**구겐하임 미술관** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["뉴욕, 1959","미국 위스콘신 라신, 1939","미국 펜실베니아, 1939"],"a":0,"why":"구겐하임은 뉴욕, 1959년이에요. 라신 1939는 존슨 왁스 본부, 펜실베니아 1939는 낙수장이에요."}],"walk":{"head":null,"parts":[{"b":[0.18,0.055,0.15,0.04],"c":[0.155,0.02,0.2,0.11],"r":2.4242,"img":"img/U9/walk/p020_22_01.jpg","say":"제목: 구겐하임미술관."},{"b":[0.36,0.025,0.555,0.515],"c":[0.3322,0,0.6105,0.5665],"r":1.4369,"img":"img/U9/walk/p020_22_02.jpg","say":"외관: 흰 띠가 감겨 올라가며 위로 갈수록 넓어져요."},{"b":[0.02,0.545,0.58,0.385],"c":[0,0.5258,0.638,0.4235],"r":2.0087,"img":"img/U9/walk/p020_22_03.jpg","say":"실내: 곡선 난간 띠를 따라 바깥쪽 벽에 작품이 걸려 있어요."},{"b":[0.625,0.57,0.32,0.36],"c":[0.609,0.552,0.352,0.396],"r":1.1852,"img":"img/U9/walk/p020_22_04.jpg","say":"단면도 SECTION A-A: 비스듬히 오르는 바닥과 꼭대기의 유리 지붕이에요."},{"b":[0.505,0.95,0.4,0.035],"c":[0.485,0.89,0.44,0.11],"r":5.3333,"img":"img/U9/walk/p020_22_05.jpg","say":"캡션: 프랭크 로이드 라이트, 구겐하임 미술관, 뉴욕, 1959."}]}},{"p":21,"title":"구겐하임 미술관의 나선형 램프와 로툰다","terms":["구겐하임 미술관","rotunda","ramp","천창 돔","Frank Lloyd Wright","S.C. Johnson Wax Headquarters","접시형 요소","모서리 없는 공간","상부 채광","천창"],"pass1":[{"kind":"say","lines":["**구겐하임 미술관** 안을 맨 위에서 내려다본 사진이에요.","커다란 **램프(ramp)** 가 빙글빙글 감기며 둥근 **로툰다(rotunda)** 를 만들어요.","램프 위의 사람들이 가운데 빈 곳 너머로 서로 보여요.","그래서 슬라이드는 '작품보다 관람객들을 전시' 한다고 해요."]}],"pass2":[{"kind":"points","head":"슬라이드 위 네 줄","items":["박물관의 주 **로툰다(rotunda)** 공간은 거대한 나선형의 **램프(ramp)** 에 의해 만들어져요.","예술 작품들은 **램프(ramp)** 의 곡선을 따라서 바깥쪽 벽에 전시해요.","방문객들은 아래 바닥 부분을 내려다보거나, 위에 있는 **천창 돔** 을 올려다볼 수 있어요.","색상은 크림색이고, 식물들이 초록색의 액센트들을 만들어 줘요."]},{"kind":"points","head":"슬라이드 아래 두 줄","items":["실내는 나선형으로 감겨 있는 램프가 있는 둥근 깔때기 형태의 공간이에요.","슬라이드는 이것을 모든 모던 빌딩들 중에서 가장 뛰어난 디자인들 중의 하나라고 해요.","작품보다 관람객들을 전시해요."]},{"kind":"compare","head":"라이트의 1939년과 1959년","cols":["","존슨 왁스 본부","구겐하임 미술관"],"rows":[["도시, 연도","미국 위스콘신 라신, 1939","뉴욕, 1959"],["핵심 모양","**접시형 요소** 를 단 기둥의 숲","나선형 **램프(ramp)**, 둥근 깔때기"],["빛","원 모양 사이 **천창**, **상부 채광**","꼭대기 **천창 돔**"],["한 마디","**모서리 없는 공간**","작품보다 관람객들을 전시"]]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**구겐하임 미술관** 에서 예술 작품은 어디에 전시될까요?","choices":["로툰다 바닥 가운데","램프의 곡선을 따라 바깥쪽 벽","천창 돔 아래 천장"],"a":1,"why":"예술 작품들은 램프의 곡선을 따라서 바깥쪽 벽에 전시해요."},{"kind":"check","q":"'작품보다 관람객들을 전시' 한다는 말이 붙은 건물은 무엇일까요?","choices":["**존슨 왁스 본부(S.C. Johnson Wax Headquarters)**","**구겐하임 미술관**","**낙수장(Falling Water, House Kaufmann)**"],"a":1,"why":"구겐하임 미술관이에요. 나선형 램프 위의 관람객들이 서로 보여요."},{"kind":"english","head":"논술 답안: 구겐하임 미술관","en":"라이트의 구겐하임 미술관(뉴욕, 1959)은 거대한 나선형 램프가 주 로툰다 공간을 만드는 둥근 깔때기 형태로, 작품은 램프 곡선을 따라 바깥쪽 벽에 전시되며 작품보다 관람객들을 전시한다.","ko":"나선형 램프 → 로툰다 → 바깥쪽 벽 전시 → 관람객 전시 순서예요.","tip":"'램프, 로툰다, 돔' 세 단어를 아래에서 위로 떠올려요."}],"walk":{"head":null,"parts":[{"b":[0.05,0.1,0.89,0.29],"c":[0.0055,0.084,0.979,0.322],"r":4.0538,"img":"img/U9/walk/p021_23_01.jpg","say":"위 네 줄: 로툰다와 램프, 바깥쪽 벽 전시, 천창 돔, 크림색과 초록 액센트."},{"b":[0.05,0.4,0.51,0.22],"c":[0.0245,0.384,0.561,0.252],"r":2.9683,"img":"img/U9/walk/p021_23_02.jpg","say":"아래 두 줄: 둥근 깔때기 형태의 공간, 작품보다 관람객들을 전시."},{"b":[0.6,0.395,0.365,0.6],"c":[0.5817,0.34,0.4015,0.66],"r":0.8111,"img":"img/U9/walk/p021_23_03.jpg","say":"사진: 위에서 내려다본 나선형 램프예요. 바닥에 사람들이 보여요."},{"b":[0.145,0.945,0.345,0.035],"c":[0.1278,0.89,0.3795,0.11],"r":4.6,"img":"img/U9/walk/p021_23_04.jpg","say":"캡션: 프랭크 로이드 라이트, 구겐하임, 뉴욕, 1959."}]}},{"p":22,"title":"알바 알토(Alvar Aalto): 건축가, 가구디자이너","terms":["Alvar Aalto","전후 모더니즘","스칸디나비아 디자인","Human Scale","파이미오 안락의자","Functionalism","Organic Architecture"],"pass1":[{"kind":"say","lines":["이제 두 번째 주인공 **알바 알토(Alvar Aalto)** 예요. 1898-1976년, 핀란드 사람이에요.","집도 짓고 의자도 만든 건축가이자 가구디자이너예요.","사진 속 휘어진 나무 의자가 **파이미오 안락의자** 예요."]},{"kind":"analogy","head":"차가운 쇠 의자 대신 따뜻한 나무 의자","scene":"공장에서 찍어 낸 차가운 쇠 의자 대신, 나무를 휘어 만든 의자를 떠올려 보세요.","map":[["공장의 반듯한 쓰임새 중심","현대적 **기능주의(Functionalism)**"],["손으로 다듬는 나무 솜씨","전통적 장인정신, 수공예"],["둘을 합친 북유럽 디자인","**스칸디나비아 디자인**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**전후 모더니즘**: 전쟁이 끝난 뒤 이어진 모더니즘이에요. 슬라이드가 알토를 부르는 말이에요.","**스칸디나비아 디자인**: 전통적 장인정신, 수공예를 현대적 **기능주의(Functionalism)** 와 결합한 디자인이에요.","**인간적 척도(Human Scale)**: 사람 몸 크기에 맞춘 크기 감각이에요.","천연목재: 자연에서 얻은 나무 그대로의 재료예요."]},{"kind":"points","head":"슬라이드에서 외울 것","items":["**알바 알토(Alvar Aalto)**, 1898-1976. 건축가, 가구디자이너예요.","**전후 모더니즘** 건축가예요.","**스칸디나비아 디자인**: 전통적 장인정신, 수공예를 현대적 **기능주의(Functionalism)** 와 결합했어요.","간결한 디자인, **인간적 척도(Human Scale)**, 천연목재의 성질을 이용한 아름다운 디자인이에요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽: 알토의 흑백 사진이에요. 캡션은 '알바 알토, 핀란드' 예요.","오른쪽 위아래: **파이미오 안락의자** 두 개예요.","팔걸이와 다리가 굽은 나무 틀 하나로 이어져요.","앉는 판도 한 장을 둥글게 휘어 만들었어요. 하나는 밝은 색, 하나는 검은색이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**스칸디나비아 디자인** 이 결합한 두 가지로 옳은 것은 무엇일까요?","choices":["전통적 장인정신, 수공예 + 현대적 기능주의","고딕 장식 + 철골 구조","기계 대량생산 + 금빛 장식"],"a":0,"why":"전통적 장인정신, 수공예를 현대적 기능주의와 결합했어요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["**인간적 척도(Human Scale)** 는 두 번 나와요.","하나는 p.16 **유기적 건축(Organic Architecture)** 의 특징 'Human Scale' 이에요.","다른 하나는 여기 알토의 **스칸디나비아 디자인** 이에요."]},{"kind":"english","head":"논술 답안: 알바 알토","en":"알바 알토(1898-1976)는 핀란드의 전후 모더니즘 건축가이자 가구디자이너로, 전통적 장인정신과 수공예를 현대적 기능주의와 결합한 스칸디나비아 디자인으로 간결함, 인간적 척도, 천연목재의 성질을 살렸다.","ko":"누구 → 스칸디나비아 디자인 → 세 가지 특징 순서예요.","tip":"파이미오 안락의자 하나를 떠올리면 나무, 사람 크기, 간결함이 같이 나와요."}],"walk":{"head":null,"parts":[{"b":[0.035,0.04,0.3,0.05],"c":[0.02,0.01,0.33,0.11],"r":4.0,"img":"img/U9/walk/p022_23_01.jpg","say":"제목: 알바 알토(Alvar Aalto)."},{"b":[0.05,0.14,0.61,0.04],"c":[0.0195,0.0922,0.671,0.1356],"r":6.5978,"img":"img/U9/walk/p022_23_02.jpg","say":"건축가, 가구디자이너. 알바 알토(Alvar Aalto, 1898-1976)."},{"b":[0.065,0.195,0.78,0.17],"c":[0.026,0.179,0.858,0.202],"r":5.6634,"img":"img/U9/walk/p022_23_03.jpg","say":"세 줄: 전후 모더니즘, 스칸디나비아 디자인, 간결함과 인간적 척도와 천연목재."},{"b":[0.27,0.4,0.3,0.565],"c":[0.255,0.3718,0.33,0.6215],"r":0.708,"img":"img/U9/walk/p022_23_04.jpg","say":"사진과 캡션: 알바 알토, 핀란드."},{"b":[0.59,0.4,0.215,0.565],"c":[0.5766,0.3718,0.2417,0.6215],"r":0.5185,"img":"img/U9/walk/p022_23_05.jpg","say":"파이미오 안락의자: 굽은 나무 틀과 휘어진 판이에요."}]}},{"p":23,"title":"알토의 유기적 건축과 파이미오 결핵요양소","terms":["Organic Architecture","Alvar Aalto","특수해","동적인 건축","낭만적 자연주의","인본주의","파이미오 결핵요양소","Falling Water, House Kaufmann","Frank Lloyd Wright"],"pass1":[{"kind":"say","lines":["**알바 알토(Alvar Aalto)** 도 **유기적 건축(Organic Architecture)** 을 했어요.","알토의 공식은 하나예요. 합리성 + 인간성 + 자연.","사진은 **파이미오 결핵요양소**, 핀란드 파이미오, 1933년이에요."]},{"kind":"compare","head":"두 사람의 유기적 건축","cols":["","라이트","알토"],"rows":[["중심","자연과의 교감","사람의 육체적, 정서적 욕구"],["대표 예","**낙수장(Falling Water, House Kaufmann)**","**파이미오 결핵요양소**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**특수해**: 어디에나 같은 답(보편해) 대신 그 장소만의 답이에요.","**동적인 건축**: 멈춰 있는 듯한 정적인 건축이 아니라 움직이는 듯한 건축이에요.","**낭만적 자연주의**: 자연을 감성적으로 바라보는 태도예요.","**인본주의**: 사람을 가장 중심에 두는 생각이에요."]},{"kind":"points","head":"알토의 유기적 건축 (슬라이드 여섯 줄)","items":["보편해보다는 **특수해** 를, 법칙과 체계보다는 다양성을 목표로 해요.","정적인 건축이 아닌 **동적인 건축** 이에요.","**낭만적 자연주의** 로부터 기원했어요.","인간의 육체적, 정서적 욕구에 대한 관심이에요.","**인본주의** 예요.","합리성 + 인간성 + 자연이에요."]},{"kind":"points","head":"사진에서 볼 것","items":["왼쪽 아래 외관: 길고 높은 흰 건물이에요. 층마다 가로로 긴 창이 이어져요.","건물 끝 쪽은 층마다 발코니가 튀어나와 있고 모서리가 둥글어요.","오른쪽 위와 아래 실내: 천장에 둥근 원판이 박혀 있어요.","오른쪽 위에는 유리 칸막이가 곡선으로 휘어 있어요. 반듯한 상자가 아니에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"알토의 **유기적 건축(Organic Architecture)** 공식으로 옳은 것은 무엇일까요?","choices":["합리성 + 인간성 + 자연","기능 + 구조 + 장식","형태 + 기능 + 기계"],"a":0,"why":"합리성 + 인간성 + 자연이에요. 단답으로 그대로 나올 수 있어요."},{"kind":"check","q":"알토의 유기적 건축 설명으로 틀린 것은 무엇일까요?","choices":["보편해보다는 **특수해**","정적인 건축이 아닌 **동적인 건축**","다양성보다 법칙과 체계를 앞세움"],"a":2,"why":"반대예요. 법칙과 체계보다는 다양성을 목표로 해요."},{"kind":"english","head":"논술 답안: 알토의 유기적 건축","en":"알토의 유기적 건축은 보편해보다 특수해를, 법칙과 체계보다 다양성을 목표로 하는 동적인 건축으로, 낭만적 자연주의에서 기원한 인본주의이며 합리성 + 인간성 + 자연으로 요약된다.","ko":"목표(특수해, 다양성) → 성격(동적) → 뿌리(낭만적 자연주의) → 인본주의 → 공식 순서예요.","tip":"마지막 공식 '합리성 + 인간성 + 자연' 은 꼭 그대로 써요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.065,0.51,0.46],"c":[0.0345,0.042,0.561,0.506],"r":1.4783,"img":"img/U9/walk/p023_23_01.jpg","say":"여섯 줄: 특수해, 동적인 건축, 낭만적 자연주의, 인간의 욕구, 인본주의, 공식."},{"b":[0.61,0.07,0.36,0.47],"c":[0.592,0.0465,0.396,0.517],"r":1.0213,"img":"img/U9/walk/p023_23_02.jpg","say":"실내: 곡선으로 휜 유리 칸막이와 둥근 천장 원판이에요."},{"b":[0.015,0.55,0.42,0.37],"c":[0,0.5315,0.462,0.407],"r":1.5135,"img":"img/U9/walk/p023_23_03.jpg","say":"외관: 길고 높은 흰 건물, 가로로 긴 창이 층마다 이어져요."},{"b":[0.45,0.55,0.42,0.37],"c":[0.429,0.5315,0.462,0.407],"r":1.5135,"img":"img/U9/walk/p023_23_04.jpg","say":"실내 홀: 기둥과 둥근 천장 원판, 노란 바닥 띠가 보여요."},{"b":[0.075,0.935,0.43,0.035],"c":[0.0535,0.89,0.473,0.11],"r":5.7333,"img":"img/U9/walk/p023_23_05.jpg","say":"캡션: 알바 알토, 파이미오 결핵요양소, 핀란드 파이미오, 1933."}]}},{"p":24,"title":"헬싱키 대학(알토 대학) 오디토리움, 핀란드 헬싱키, 1966","terms":["헬싱키 대학 오디토리움","Alvar Aalto","형태의 창조자"],"pass1":[{"kind":"say","lines":["붉은 벽돌 건물과 커다란 강당 사진이에요.","**알바 알토(Alvar Aalto)** 의 **헬싱키 대학 오디토리움**, 핀란드 헬싱키, 1966년이에요.","알토는 자연재료를 좋아했고 '**형태의 창조자**' 로 불렸어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["오디토리움: 많은 사람이 앉아 강연을 듣는 강당이에요.","**형태의 창조자**: 알토를 부르는 별명이에요.","자연재료: 벽돌, 나무처럼 자연에서 온 재료예요."]},{"kind":"points","head":"사진에서 볼 것","items":["슬라이드 캡션은 '헬싱키 대학(알토 대학) 오디토리움, 핀란드 헬싱키, 1966' 이에요.","왼쪽 외관: 붉은 벽돌 벽 위로 녹색 지붕이 부채꼴처럼 펼쳐져요.","지붕 아래 창들이 계단처럼 층층이 올라가요.","오른쪽 실내: 흰 천장이 곡면 띠처럼 휘어 내려와요.","나무 좌석이 부채꼴로 층층이 놓여 있어요. 벽돌과 나무, 자연재료 선호가 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"'**형태의 창조자**' 로 불린 사람은 누구일까요?","choices":["**프랭크 로이드 라이트(Frank Lloyd Wright)**","**알바 알토(Alvar Aalto)**"],"a":1,"why":"알토예요. 헬싱키 대학 오디토리움 슬라이드에 나와요."},{"kind":"check","q":"**헬싱키 대학 오디토리움** 의 연도는 언제일까요?","choices":["1933","1957","1966"],"a":2,"why":"1966이에요. 1933은 파이미오 결핵요양소, 1957은 한자지구 아파트예요."}],"walk":{"head":null,"parts":[{"b":[0.02,0.14,0.525,0.57],"c":[0,0.1115,0.5775,0.627],"r":1.2281,"img":"img/U9/walk/p024_22_01.jpg","say":"외관: 붉은 벽돌 벽과 부채꼴로 펼쳐진 녹색 지붕이에요."},{"b":[0.563,0.14,0.415,0.67],"c":[0.5423,0.1065,0.4565,0.737],"r":0.8259,"img":"img/U9/walk/p024_22_02.jpg","say":"실내: 곡면 띠 천장과 부채꼴로 놓인 나무 좌석이에요."},{"b":[0.055,0.815,0.26,0.105],"c":[0.042,0.799,0.286,0.137],"r":2.7835,"img":"img/U9/walk/p024_22_03.jpg","say":"두 줄: 자연재료 선호, '형태의 창조자' 로 불림."},{"b":[0.67,0.825,0.27,0.075],"c":[0.6565,0.8075,0.297,0.11],"r":3.6,"img":"img/U9/walk/p024_22_04.jpg","say":"캡션: 알바 알토, 헬싱키 대학(알토 대학) 오디토리움, 핀란드 헬싱키, 1966."}]}},{"p":25,"title":"Alvar Aalto 주택의 특징과 메종 카레","terms":["반균질공간","부정형","시각적 밸런스","Alvar Aalto","메종 카레","Mairea","Aalto House & Studio"],"pass1":[{"kind":"say","lines":["**알바 알토(Alvar Aalto)** 가 지은 집들의 공통점이에요.","어디나 똑같은 네모 방이 아니에요. 들쭉날쭉하고 흘러가듯 이어져요.","사진은 **메종 카레**, 프랑스 기욘, 1959년이에요."]},{"kind":"analogy","head":"퍼즐 조각을 마음 가는 대로 이어 붙인 그림","scene":"조각을 반듯하게 줄 세우지 않았는데도 전체가 보기 좋은 그림을 떠올려 보세요.","map":[["어디나 똑같지 않은 방","**반균질공간**"],["반듯하지 않은 전체 윤곽","**부정형**"],["줄 맞춤 대신 눈으로 맞춘 균형","**시각적 밸런스**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**반균질공간**: 어디나 똑같은 공간을 거부한 공간이에요.","**부정형**: 반듯하게 정해진 모양이 아닌 형태예요.","**시각적 밸런스**: 규칙적 반복 대신 눈으로 보아 균형이 맞게 하는 것이에요.","지양: 하지 않으려고 피한다는 뜻이에요."]},{"kind":"points","head":"Alvar Aalto 주택의 특징 (슬라이드)","items":["**반균질공간** 의 건축이에요.","공간구성 1: 전체 윤곽은 **부정형** 이에요.","공간구성 2: L 또는 ㄷ자형 형태로 외부공간을 둘러싸요.","공간구성 3: 공간을 서로 이어서 유동적으로 만들어요.","공간구성 4: 구조나 형태의 규칙적 반복을 지양해요.","공간구성 5: 규칙성보다 **시각적 밸런스** 를 추구해요."]},{"kind":"points","head":"사례 세 채와 사진","items":["목록: Aalto 주택(1936), Mairea 주택(1939), Carre 주택(1959)이에요.","Carre 주택이 사진의 **메종 카레**(프랑스 기욘, 1959)예요.","Mairea 주택은 p.28 의 **빌라 마이레아(Mairea)** 예요.","사진: 흰 벽 위로 지붕이 한쪽으로 길게 기울어 있어요.","평면: 방들이 들쭉날쭉 튀어나와서 윤곽이 **부정형** 이에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"Alvar Aalto 주택의 특징이 아닌 것은 무엇일까요?","choices":["전체 윤곽은 **부정형**","구조나 형태의 규칙적 반복","L 또는 ㄷ자형으로 외부공간을 둘러쌈"],"a":1,"why":"규칙적 반복은 지양해요. 규칙성보다 시각적 밸런스를 추구해요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["목록의 'Aalto 주택(1936)' 과 p.26 캡션의 **알토 자택 겸 스튜디오(Aalto House & Studio)** 1939는 연도가 달라요.","슬라이드만으로는 같은 집인지 알 수 없어요. 두 표기를 따로 외워요.","같은 작품, 다른 이름: Carre 주택 = **메종 카레**, Mairea 주택 = **빌라 마이레아(Mairea)**.","원문 '외부공간을 둘러싼 L 또는 ㄷ 자형 형태로 외부공간을 둘러쌈' 은 같은 말이 겹쳐 있어요."]},{"kind":"english","head":"논술 답안: 알토 주택의 특징","en":"알토 주택은 반균질공간의 건축으로, 전체 윤곽이 부정형이고 L 또는 ㄷ자형으로 외부공간을 둘러싸며, 공간을 이어 유동적으로 만들고 규칙적 반복 대신 시각적 밸런스를 추구한다.","ko":"반균질공간 → 부정형 → L, ㄷ자형 → 유동적 → 시각적 밸런스 순서예요.","tip":"사례 연도 36, 39, 59를 뒤에 붙이면 답안이 더 단단해져요."}],"walk":{"head":null,"parts":[{"b":[0.06,0.055,0.285,0.045],"c":[0.0457,0.0225,0.3135,0.11],"r":3.8,"img":"img/U9/walk/p025_23_01.jpg","say":"제목: Alvar Aalto 주택의 특징."},{"b":[0.065,0.125,0.235,0.045],"c":[0.053,0.0925,0.259,0.11],"r":3.1394,"img":"img/U9/walk/p025_23_02.jpg","say":"반균질공간의 건축."},{"b":[0.065,0.19,0.69,0.345],"c":[0.0305,0.1728,0.759,0.3795],"r":2.6667,"img":"img/U9/walk/p025_23_03.jpg","say":"공간구성 다섯 줄: 부정형, L 또는 ㄷ자형, 유동적 연결, 반복 지양, 시각적 밸런스."},{"b":[0.065,0.555,0.59,0.04],"c":[0.0355,0.5094,0.649,0.1311],"r":6.6006,"img":"img/U9/walk/p025_23_04.jpg","say":"사례: Aalto 주택(1936), Mairea 주택(1939), Carre 주택(1959)."},{"b":[0.225,0.605,0.41,0.37],"c":[0.2045,0.5865,0.451,0.407],"r":1.4775,"img":"img/U9/walk/p025_23_05.jpg","say":"사진: 한쪽으로 길게 기운 지붕과 흰 벽이에요."},{"b":[0.68,0.495,0.32,0.5],"c":[0.648,0.45,0.352,0.55],"r":0.8533,"img":"img/U9/walk/p025_23_06.jpg","say":"평면과 캡션: 알바 알토, 메종 카레, 프랑스 기욘, 1959."}]}},{"p":26,"title":"Aalto 자택 겸 스튜디오 (캡션만 있는 슬라이드)","terms":["Aalto House & Studio","Alvar Aalto"],"pass1":[{"kind":"say","lines":["**알바 알토(Alvar Aalto)** 가 살면서 일한 집, **알토 자택 겸 스튜디오(Aalto House & Studio)** 예요.","슬라이드 글자는 제목과 캡션뿐이에요. 캡션은 1939년이에요.","흰 벽과 짙은 나무 판이 한 집에 같이 붙어 있어요."]}],"pass2":[{"kind":"points","head":"이 쪽 이름 정리","items":["영어 제목: Aalto House & Studio.","캡션: 알바 알토, Aalto 자택 겸 스튜디오, 1939.","자택 겸 스튜디오: 사는 집이면서 일하는 작업실이라는 뜻이에요."]},{"kind":"points","head":"사진에서 보이는 것만","items":["가운데 위: 흰 칠을 한 높은 벽에 네모난 창이 하나 나 있어요.","왼쪽 아래: 길가에서 본 모습이에요. 흰 벽 위에 짙은 나무 판 덩어리가 얹혀 있어요.","흰 벽에 나무 문과 큰 나무 문이 박혀 있고, 담을 덩굴이 덮었어요.","오른쪽: 짙은 세로 나무 판 아래로 주황빛 나무 문이 있어요. 양옆을 붉은 덩굴이 덮었어요.","흰 벽, 나무, 덩굴 식물이 한 집에 섞여 있어요. 재료가 한 가지가 아니에요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**알토 자택 겸 스튜디오(Aalto House & Studio)** 사진 캡션의 연도는 언제일까요?","choices":["1933","1936","1939"],"a":2,"why":"캡션은 1939예요. 1936은 p.25 목록의 'Aalto 주택' 표기예요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["캡션 연도는 1939년이고, p.25 목록은 'Aalto 주택(1936)' 이에요.","문제에 어느 표기가 나왔는지 보고 답해요."]}],"walk":{"head":null,"parts":[{"b":[0.055,0.035,0.21,0.04],"c":[0.043,0.0,0.234,0.11],"r":2.8364,"img":"img/U9/walk/p026_22_01.jpg","say":"제목: Aalto House & Studio."},{"b":[0.25,0.075,0.255,0.445],"c":[0.2372,0.0527,0.2805,0.4895],"r":0.764,"img":"img/U9/walk/p026_22_02.jpg","say":"가운데 위: 흰 벽에 네모난 창, 뒤로 나무 판 2층이 보여요."},{"b":[0.035,0.565,0.48,0.39],"c":[0.011,0.5455,0.528,0.429],"r":1.641,"img":"img/U9/walk/p026_22_03.jpg","say":"왼쪽 아래: 길가에서 본 흰 벽과 짙은 나무 판이에요."},{"b":[0.553,0.07,0.447,0.83],"c":[0.5083,0.0285,0.4917,0.913],"r":0.7181,"img":"img/U9/walk/p026_22_04.jpg","say":"오른쪽: 나무 판 벽 아래 주황빛 나무 문과 붉은 덩굴이에요."},{"b":[0.635,0.94,0.31,0.035],"c":[0.6195,0.89,0.341,0.11],"r":4.1333,"img":"img/U9/walk/p026_22_05.jpg","say":"캡션: 알바 알토, Aalto 자택 겸 스튜디오, 1939."}]}},{"p":27,"title":"Aalto 자택 겸 스튜디오의 평면, 거실, 테라스","terms":["Aalto House & Studio","Alvar Aalto","부정형","파이미오 안락의자"],"pass1":[{"kind":"say","lines":["같은 **알토 자택 겸 스튜디오(Aalto House & Studio)** 의 평면과 실내예요.","위에는 평면 두 장, 아래에는 거실과 테라스 사진이 있어요.","캡션은 앞 쪽과 같아요. 1939년이에요."]}],"pass2":[{"kind":"points","head":"사진과 평면에서 보이는 것만","items":["위 평면 두 장: 방들이 반듯한 네모로 딱 맞지 않고 들쭉날쭉해요.","오른쪽 평면은 가운데에 줄무늬로 칠한 넓은 칸이 길게 이어져요.","아래 왼쪽 거실: 그랜드 피아노, 벽난로, 나무 바닥이 보여요.","의자 하나는 팔걸이가 굽은 나무 틀이에요. **파이미오 안락의자** 처럼 나무를 휘었어요.","아래 오른쪽 테라스: 흰 기둥 처마 아래 판석 바닥 마당이에요. 덩굴이 벽을 덮었어요."]},{"kind":"points","head":"p.25 와 이어 보기","items":["평면의 들쭉날쭉한 윤곽을 보면 p.25 의 '전체 윤곽은 **부정형**' 이 떠올라요.","실내, 테라스, 정원이 한 장면에 이어져 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**알토 자택 겸 스튜디오(Aalto House & Studio)** 의 슬라이드 영어 제목은 무엇일까요?","choices":["Aalto House & Studio","Mairea","Hansa"],"a":0,"why":"Aalto House & Studio예요. Mairea는 빌라 마이레아, Hansa는 한자지구 아파트예요."}],"walk":{"head":null,"parts":[{"b":[0.17,0.01,0.37,0.42],"c":[0.1515,0,0.407,0.462],"r":1.1746,"img":"img/U9/walk/p027_22_01.jpg","say":"왼쪽 평면: 방들이 들쭉날쭉 이어져요."},{"b":[0.57,0.01,0.375,0.42],"c":[0.5513,0,0.4125,0.462],"r":1.1905,"img":"img/U9/walk/p027_22_02.jpg","say":"오른쪽 평면: 줄무늬로 칠한 넓은 칸이 가운데를 차지해요."},{"b":[0.027,0.488,0.51,0.49],"c":[0.0015,0.461,0.561,0.539],"r":1.3878,"img":"img/U9/walk/p027_22_03.jpg","say":"거실: 그랜드 피아노, 벽난로, 굽은 나무 팔걸이 의자예요."},{"b":[0.564,0.5,0.4,0.33],"c":[0.544,0.4835,0.44,0.363],"r":1.6162,"img":"img/U9/walk/p027_22_04.jpg","say":"테라스: 흰 기둥 처마와 판석 바닥, 덩굴 벽이에요."},{"b":[0.635,0.94,0.31,0.035],"c":[0.6195,0.89,0.341,0.11],"r":4.1333,"img":"img/U9/walk/p027_22_05.jpg","say":"캡션: 알바 알토, Aalto 자택 겸 스튜디오, 1939."}]}},{"p":28,"title":"빌라 마이레아(Mairea), 노르마르크, 핀란드, 1939","terms":["Mairea","Alvar Aalto","International Style","internationale Architektur","건축적 콜라주","S자의 유동적 내부공간","Falling Water, House Kaufmann","S.C. Johnson Wax Headquarters","Aalto House & Studio"],"pass1":[{"kind":"say","lines":["**빌라 마이레아(Mairea)** 예요. 핀란드 노르마르크, 1939년이에요.","반듯한 **국제주의 양식(International Style)** 에 나무와 자유로운 모양을 더했어요.","왼쪽 배치 평면에 구불구불한 자유 곡선 수영장이 보여요."]},{"kind":"analogy","head":"오려 붙인 콜라주 같은 집","scene":"색종이, 나무 조각, 천을 오려 한 장에 붙인 콜라주를 떠올려 보세요.","map":[["흰 벽, 나무 판, 돌을 섞은 외관","**건축적 콜라주**"],["S자로 굽이굽이 이어지는 실내","**S자의 유동적 내부공간** 연결"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**국제주의 양식(International Style)**: 4단원에서 본 반듯하고 질서 정연한 근대 건축 양식이에요.","**건축적 콜라주**: 여러 재료와 형태를 오려 붙인 듯 섞은 외관이에요.","**S자의 유동적 내부공간**: S자로 흐르듯 이어지는 실내 공간 연결이에요."]},{"kind":"points","head":"슬라이드 네 줄","items":["**국제주의 양식(International Style)** 의 질서 정연하고 논리적인 사고방식과 함께, 자연 소재들과 좀 더 자유스런 형태들을 감성적이고 낭만적으로 활용했어요.","많은 시각적인 다양성과 함께 사용의 다양성을 제공하는 편안하고 흐르는 듯한 형태로 배열했어요.","외관은 **건축적 콜라주** 예요. 형태적으로나 의미적으로 작품을 풍성하게 완성해요.","**S자의 유동적 내부공간** 연결이에요."]},{"kind":"points","head":"평면과 사진에서 볼 것","items":["왼쪽 배치 평면: 건물이 한 번 꺾여 마당 쪽을 감싸고, 마당에 자유 곡선 수영장이 있어요.","p.25 의 'L 또는 ㄷ자형으로 외부공간을 둘러쌈' 을 떠올리게 해요.","오른쪽 사진: 2층은 짙은 나무 판, 위층은 흰 벽, 아래는 돌 기단이에요.","왼쪽 끝에는 나무로 감싼 둥근 덩어리가 붙어 있어요. 한 집에 재료가 여러 가지예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**빌라 마이레아(Mairea)** 의 외관을 슬라이드는 무엇이라고 부를까요?","choices":["건축적 콜라주","반듯한 유리 상자","고전 기둥 장식"],"a":0,"why":"외관은 건축적 콜라주예요. 형태적으로나 의미적으로 작품을 풍성하게 완성해요."},{"kind":"check","q":"**빌라 마이레아(Mairea)** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["노르마르크, 핀란드, 1939","프랑스 기욘, 1959","독일 베를린, 1957"],"a":0,"why":"노르마르크, 핀란드, 1939예요. 기욘 1959는 메종 카레, 베를린 1957은 한자지구 아파트예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["1939년은 네 작품의 해예요.","라이트의 **낙수장(Falling Water, House Kaufmann)** 와 **존슨 왁스 본부(S.C. Johnson Wax Headquarters)** 예요.","알토의 **알토 자택 겸 스튜디오(Aalto House & Studio)** 와 **빌라 마이레아(Mairea)** 예요.","**국제주의 양식(International Style)**, **국제주의 건축(internationale Architektur)** 은 4단원 말이에요. 알토는 그 질서에 자연을 더했어요."]},{"kind":"english","head":"논술 답안: 빌라 마이레아","en":"알토의 빌라 마이레아(노르마르크, 핀란드, 1939)는 국제주의 양식의 질서 정연하고 논리적인 사고방식에 자연 소재와 자유로운 형태를 감성적, 낭만적으로 더하였고, 외관은 건축적 콜라주이며 S자의 유동적 내부공간으로 연결된다.","ko":"국제주의 + 자연 → 콜라주 외관 → S자 내부 순서예요.","tip":"'질서 + 자연 = 콜라주, 실내는 S자' 로 외워요."}],"walk":{"head":null,"parts":[{"b":[0.43,0.04,0.205,0.04],"c":[0.418,0.005,0.229,0.11],"r":2.7758,"img":"img/U9/walk/p028_23_01.jpg","say":"제목: 빌라 마이레아(Mairea)."},{"b":[0.0,0.12,0.41,0.805],"c":[0,0.0797,0.451,0.8855],"r":0.6791,"img":"img/U9/walk/p028_23_02.jpg","say":"배치 평면: 꺾인 건물과 자유 곡선 수영장이에요."},{"b":[0.415,0.14,0.565,0.445],"c":[0.3785,0.1178,0.6215,0.4895],"r":1.6929,"img":"img/U9/walk/p028_23_03.jpg","say":"네 줄: 국제주의 양식 + 자연 소재, 다양성, 건축적 콜라주, S자 내부공간."},{"b":[0.47,0.61,0.52,0.36],"c":[0.428,0.592,0.572,0.396],"r":1.9259,"img":"img/U9/walk/p028_23_04.jpg","say":"외관: 나무 판, 흰 벽, 돌, 둥근 나무 덩어리가 섞여 있어요."},{"b":[0.045,0.953,0.4,0.032],"c":[0.025,0.89,0.44,0.11],"r":5.3333,"img":"img/U9/walk/p028_23_05.jpg","say":"캡션: 알바 알토, 빌라 마이레아, 노르마르크, 핀란드, 1939."}]}},{"p":29,"title":"빌라 마이레아의 외관 두 컷","terms":["Mairea","Alvar Aalto","건축적 콜라주","시각적 밸런스"],"pass1":[{"kind":"say","lines":["**빌라 마이레아(Mairea)** 사진 두 장이에요. 글자는 제목뿐이에요.","위는 수영장 쪽 마당, 아래는 소나무 숲 쪽에서 본 모습이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["위: 흰 벽 건물이 꺾여서 잔디 마당과 수영장을 감싸요.","수영장 가장자리가 반듯하지 않고 구불구불한 곡선이에요.","오른쪽 끝에는 짙은 나무로 감싼 덩어리가 붙어 있어요.","아래: 키 큰 소나무 사이로 나무 판 2층과 흰 벽 위층이 보여요.","흰 벽, 나무 판, 덩굴, 숲이 한 화면에 섞여요. p.28 의 **건축적 콜라주** 를 눈으로 확인해요."]},{"kind":"points","head":"p.25 와 이어 보기","items":["건물이 마당을 감싸는 모습은 'L 또는 ㄷ자형으로 외부공간을 둘러쌈' 과 맞닿아요.","덩어리마다 재료와 모양이 달라요. 반복 대신 **시각적 밸런스** 로 맞췄어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**빌라 마이레아(Mairea)** 사진에서 수영장은 어떤 모양일까요?","choices":["반듯한 직사각형","구불구불한 자유 곡선","정원 가운데의 둥근 원"],"a":1,"why":"가장자리가 구불구불한 자유 곡선이에요. 반듯한 상자와 반대인 모양이에요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.04,0.205,0.04],"c":[0.028,0.005,0.229,0.11],"r":2.7758,"img":"img/U9/walk/p029_22_01.jpg","say":"제목: 빌라 마이레아(Mairea)."},{"b":[0.29,0.015,0.555,0.51],"c":[0.2622,0,0.6105,0.561],"r":1.451,"img":"img/U9/walk/p029_22_02.jpg","say":"위: 꺾인 흰 벽 건물이 곡선 수영장과 마당을 감싸요."},{"b":[0.185,0.55,0.605,0.43],"c":[0.1547,0.527,0.6655,0.473],"r":1.876,"img":"img/U9/walk/p029_22_03.jpg","say":"아래: 소나무 숲 사이의 나무 판 2층과 흰 벽이에요."}]}},{"p":30,"title":"빌라 마이레아의 실내: 침엽수림의 추상적 표현","terms":["Mairea","침엽수림의 추상적 표현","S자의 유동적 내부공간","Alvar Aalto"],"pass1":[{"kind":"say","lines":["**빌라 마이레아(Mairea)** 의 실내예요.","계단 옆에 나무 막대가 숲의 나무줄기처럼 줄지어 서 있어요.","핀란드 숲을 집 안으로 들여온 거예요. 이것이 **침엽수림의 추상적 표현** 이에요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["**침엽수림의 추상적 표현**: 핀란드 숲을 실내 요소로 단순하게 옮긴 표현이에요.","침엽수: 소나무처럼 잎이 바늘같이 뾰족한 나무예요.","추상적 표현: 그대로 그리지 않고 특징만 단순하게 뽑아낸 표현이에요."]},{"kind":"points","head":"슬라이드 두 줄","items":["핀란드 대부분에서 볼 수 있는 **침엽수림의 추상적 표현** 이에요.","전통과 감성: 곡면, 목재, 빛이에요."]},{"kind":"points","head":"사진에서 보이는 것만","items":["큰 사진: 계단 난간 쪽에 가는 나무 막대가 세로로 촘촘히 서 있어요.","검은 기둥 하나는 가운데를 끈 같은 것으로 감았어요.","천장은 가는 나무 널을 촘촘히 붙였고, 바닥은 붉은 타일이에요.","작은 사진: 계단 몇 단을 오르면 벽난로가 있는 거실이에요. 바닥 경계가 곡선이에요.","공간이 문 없이 이어져요. p.28 의 **S자의 유동적 내부공간** 을 떠올려요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**빌라 마이레아(Mairea)** 실내의 '전통과 감성' 세 단어는 무엇일까요?","choices":["곡면, 목재, 빛","철, 유리, 콘크리트","직선, 흰색, 반복"],"a":0,"why":"곡면, 목재, 빛이에요."},{"kind":"english","head":"논술 답안: 빌라 마이레아의 실내","en":"빌라 마이레아의 실내는 핀란드 대부분에서 볼 수 있는 침엽수림을 추상적으로 표현하였고, 곡면, 목재, 빛으로 전통과 감성을 드러낸다.","ko":"숲(침엽수림) → 세 단어(곡면, 목재, 빛) 순서예요.","tip":"'곡, 목, 빛' 세 글자로 줄여 외워요."}],"walk":{"head":null,"parts":[{"b":[0.067,0.045,0.59,0.61],"c":[0.0375,0.0145,0.649,0.671],"r":1.2896,"img":"img/U9/walk/p030_23_01.jpg","say":"큰 사진: 계단 옆 세로 나무 막대가 숲처럼 서 있어요."},{"b":[0.71,0.06,0.205,0.04],"c":[0.698,0.025,0.229,0.11],"r":2.7758,"img":"img/U9/walk/p030_23_02.jpg","say":"제목: 빌라 마이레아(Mairea)."},{"b":[0.065,0.7,0.465,0.16],"c":[0.0417,0.684,0.5115,0.192],"r":3.5521,"img":"img/U9/walk/p030_23_03.jpg","say":"두 줄: 침엽수림의 추상적 표현, 전통과 감성(곡면, 목재, 빛)."},{"b":[0.56,0.56,0.428,0.4],"c":[0.5292,0.54,0.4708,0.44],"r":1.4267,"img":"img/U9/walk/p030_23_04.jpg","say":"작은 사진: 계단 위 벽난로 거실과 나무 막대 칸막이예요."}]}},{"p":31,"title":"알토 주거의 실내 1: 빛, 안락함, 따뜻함 (작품 이름 없음)","terms":["Alvar Aalto","ramp","구겐하임 미술관"],"pass1":[{"kind":"say","lines":["사진 두 장과 글 세 줄이에요. 작품 이름 캡션은 없어요.","**알바 알토(Alvar Aalto)** 주거 작품의 실내 분위기를 말해요.","큰 창으로 빛이 가득, 의자는 편안, 밤에는 등불. 한마디로 따뜻해요."]}],"pass2":[{"kind":"points","head":"슬라이드 세 줄","items":["광활한 전원 주택의 거실에 있는 커다란 창문들은 그 공간을 빛으로 채워 줘요.","의자들이 앉았을 때의 안락함을 제공하고, 램프와 매달려 있는 랜턴 등이 밤 시간의 조명을 제공해요.","안정되고 따뜻한 느낌은 알토의 주거 작품들이 가지는 전형적인 특징이에요."]},{"kind":"points","head":"사진에서 보이는 것만","items":["위: 나무 천장 가운데에 둥근 원이 밝게 뚫려 있어요.","벽에는 사다리 같은 나무 틀과 밧줄이 있고, 둥근 탁자와 작은 의자들이 놓여 있어요.","아래: 큰 창 가득 덩굴 식물이 드리워 있고, 등나무 의자 두 개가 놓여 있어요.","기둥은 나무 띠로 감쌌고, 오른쪽에 키 큰 스탠드 조명이 있어요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"알토 주거 작품의 전형적인 특징으로 슬라이드가 말한 것은 무엇일까요?","choices":["안정되고 따뜻한 느낌","차갑고 기계적인 느낌","화려한 금빛 장식"],"a":0,"why":"안정되고 따뜻한 느낌이 알토 주거 작품의 전형적인 특징이에요."},{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드에는 작품 이름이 적혀 있지 않아요. 이름을 지어 붙이지 않아요.","여기의 '램프' 는 조명 기구예요.","**구겐하임 미술관** 의 **램프(ramp)** 는 비탈진 통로예요. 소리만 같아요."]}],"walk":{"head":null,"parts":[{"b":[0.016,0.027,0.535,0.47],"c":[0,0.0035,0.5885,0.517],"r":1.5177,"img":"img/U9/walk/p031_22_01.jpg","say":"위 사진: 나무 천장의 둥근 원, 둥근 탁자와 작은 의자들이에요."},{"b":[0.02,0.527,0.527,0.433],"c":[0,0.5054,0.5797,0.4763],"r":1.6228,"img":"img/U9/walk/p031_22_02.jpg","say":"아래 사진: 큰 창과 덩굴 식물, 등나무 의자, 스탠드 조명이에요."},{"b":[0.574,0.195,0.395,0.435],"c":[0.5542,0.1732,0.4345,0.4785],"r":1.2107,"img":"img/U9/walk/p031_22_03.jpg","say":"세 줄: 큰 창의 빛, 의자의 안락함과 밤 조명, 안정되고 따뜻한 느낌."}]}},{"p":32,"title":"알토 주거의 실내 2: 현관은 매우 중요한 공간 (작품 이름 없음)","terms":["Alvar Aalto"],"pass1":[{"kind":"say","lines":["글 두 줄과 실내 사진 세 장이에요. 이번에도 작품 이름은 없어요.","현관은 매우 중요한 공간이에요. 공간과 공간을 부드럽게 이어 줘요."]}],"pass2":[{"kind":"points","head":"이 쪽의 낱말 뜻","items":["현관: 집에 들어서면 처음 만나는 공간이에요.","부드럽게 연결: 문으로 뚝 끊지 않고 다음 공간으로 자연스럽게 넘어가게 하는 것이에요."]},{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽: 한 단 높은 바닥에서 거실을 내려다본 모습이에요. 끝에 숲이 보이는 큰 창이 있어요.","천장은 짙은 나무 널이고 비스듬히 기울어 있어요.","오른쪽 위: 흰 벽 덩어리 너머로 거실이 이어져요. 천장에 등이 매달려 있어요.","오른쪽 아래: 흰 벽난로 아래에 장작이 쌓여 있고, 왼쪽에 계단 몇 단이 있어요.","문 대신 바닥 높이와 벽 덩어리로 공간을 나눠요. 그래서 공간이 끊기지 않고 이어져요."]},{"kind":"points","head":"p.25 와 이어 보기","items":["p.25 의 '공간을 서로 이어서 유동적으로 만듬' 과 같은 생각이에요.","**알바 알토(Alvar Aalto)** 의 집에서 현관은 공간과 공간을 잇는 이음매예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"슬라이드가 알토 주거에서 '매우 중요한 공간' 이라고 한 곳은 어디일까요?","choices":["현관","다락","지하실"],"a":0,"why":"현관이에요. 공간과 공간을 부드럽게 연결해요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.08,0.34,0.105],"c":[0.023,0.064,0.374,0.137],"r":3.6399,"img":"img/U9/walk/p032_23_01.jpg","say":"두 줄: 현관은 매우 중요한 공간, 공간과 공간을 부드럽게 연결."},{"b":[0.083,0.268,0.386,0.71],"c":[0.0637,0.219,0.4246,0.781],"r":0.7249,"img":"img/U9/walk/p032_23_02.jpg","say":"왼쪽: 한 단 높은 곳에서 본 거실과 숲 쪽 큰 창이에요."},{"b":[0.54,0.04,0.35,0.457],"c":[0.5225,0.0171,0.385,0.5027],"r":1.0212,"img":"img/U9/walk/p032_23_03.jpg","say":"오른쪽 위: 흰 벽 덩어리 너머로 이어지는 거실이에요."},{"b":[0.54,0.52,0.35,0.46],"c":[0.5225,0.494,0.385,0.506],"r":1.0145,"img":"img/U9/walk/p032_23_04.jpg","say":"오른쪽 아래: 흰 벽난로와 쌓인 장작, 옆의 계단이에요."}]}},{"p":33,"title":"한자(Hansa)지구 아파트, 독일 베를린, 1957","terms":["Hansa","Alvar Aalto","모듈화된 유닛","단일 색채"],"pass1":[{"kind":"say","lines":["이번에는 집 한 채가 아니라 큰 아파트예요.","**알바 알토(Alvar Aalto)** 의 **한자지구 아파트(Hansa)**, 독일 베를린, 1957년이에요.","같은 판을 반복해 붙이고, 색은 한 가지만 썼어요."]},{"kind":"analogy","head":"같은 크기 블록으로 쌓은 아파트","scene":"같은 크기 레고 블록으로 벽을 쌓으면 이음새가 저절로 격자가 되죠.","map":[["같은 크기 블록","**모듈화된 유닛**"],["블록 사이 이음새","마감재의 줄눈 → 격자형 패턴"],["한 가지 색 블록","**단일 색채**"]]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["파사드: 건물의 바깥 얼굴, 정면 외벽이에요.","콘크리트 슬래브: 콘크리트로 만든 넓적한 판이에요.","**모듈화된 유닛**: 같은 크기 단위로 규격화한 부품이에요.","줄눈: 판과 판 사이의 이음새 줄이에요.","**단일 색채**: 한 가지 색만 쓰는 것이에요."]},{"kind":"points","head":"슬라이드 네 줄","items":["전체 파사드는 콘크리트 슬래브의 반복으로 구성해요.","건축요소인 창과 문, 창틀은 디테일에 따라 **모듈화된 유닛** 에 의해 구성해요.","마감재의 줄눈에서 격자형 패턴을 자연스럽게 형성해요.","단순성과 구조적인 아름다움을 **단일 색채** 사용으로 더욱 강조해요."]},{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽: 발코니가 층마다 같은 모양으로 튀어나와 쭉 반복돼요.","오른쪽 흑백: 높은 건물 두 동이에요. 벽 판의 이음새가 격자처럼 보여요.","창 크기와 간격이 규칙적이에요. 색은 한 가지예요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**한자지구 아파트(Hansa)** 의 도시와 연도로 옳은 것은 무엇일까요?","choices":["독일 베를린, 1957","핀란드 헬싱키, 1966","프랑스 기욘, 1959"],"a":0,"why":"독일 베를린, 1957이에요. 헬싱키 1966은 헬싱키 대학 오디토리움, 기욘 1959는 메종 카레예요."},{"kind":"check","q":"**한자지구 아파트(Hansa)** 에서 단순성과 구조적인 아름다움을 더욱 강조한 것은 무엇일까요?","choices":["**단일 색채** 사용","화려한 타일 장식","곡선 유리벽"],"a":0,"why":"단일 색채 사용으로 더욱 강조해요."}],"walk":{"head":null,"parts":[{"b":[0.055,0.095,0.215,0.035],"c":[0.043,0.0575,0.239,0.11],"r":2.897,"img":"img/U9/walk/p033_23_01.jpg","say":"제목: 한자(Hansa)지구 아파트."},{"b":[0.44,0.06,0.53,0.315],"c":[0.4135,0.044,0.583,0.347],"r":2.2402,"img":"img/U9/walk/p033_23_02.jpg","say":"네 줄: 슬래브 반복, 모듈화된 유닛, 줄눈의 격자형 패턴, 단일 색채."},{"b":[0.033,0.264,0.377,0.662],"c":[0.0141,0.2309,0.4147,0.7282],"r":0.7593,"img":"img/U9/walk/p033_23_03.jpg","say":"왼쪽: 같은 모양 발코니가 층마다 반복돼요."},{"b":[0.433,0.405,0.544,0.525],"c":[0.4016,0.3787,0.5984,0.5775],"r":1.3816,"img":"img/U9/walk/p033_23_04.jpg","say":"오른쪽: 두 동의 외관이에요. 판 이음새가 격자처럼 보여요."},{"b":[0.57,0.948,0.397,0.032],"c":[0.5501,0.89,0.4367,0.11],"r":5.2933,"img":"img/U9/walk/p033_23_05.jpg","say":"캡션: 알바 알토, 한자지구 아파트 블록, 독일 베를린, 1957."}]}},{"p":34,"title":"한자지구 아파트의 ㄷ자 매스와 꺾인 평면","terms":["Hansa","클러스터 형식","Alvar Aalto","시각적 밸런스"],"pass1":[{"kind":"say","lines":["같은 **한자지구 아파트(Hansa)** 예요. 이번에는 모양 이야기예요.","양 끝은 통통하고 가운데는 홀쭉한 ㄷ자 건물이에요.","판은 반듯하게 반복하지만, 전체 모양은 비틀리고 꺾여 있어요."]}],"pass2":[{"kind":"points","head":"이 쪽의 용어 뜻","items":["매스: 건물 덩어리 전체의 부피감이에요.","**클러스터 형식**: 단위세대를 송이처럼 한데 모아 묶은 배치예요.","단위세대: 한 가구가 사는 집 한 칸이에요.","정형적인 축: 반듯하게 정해진 기준선이에요."]},{"kind":"points","head":"슬라이드 네 줄","items":["매스의 양 끝단이 부풀려지고 가운데 깊이가 좁은 ㄷ자 형태의 건물이에요.","이 볼륨감 있는 매스는 블록플랜상 건물의 남측과 북측 양 끝단에 **클러스터 형식** 으로 단위세대를 배치한 결과예요.","그리드를 벗어난 평면 배치 역시 매스에 변화감을 주는 요인이에요.","정형적인 축에서 벗어나 비틀어지고 꺾인 자유로운 비대칭 형상이에요."]},{"kind":"points","head":"사진과 평면에서 볼 것","items":["사진: 아래에서 올려다본 모습이에요. 양쪽 날개가 앞으로 튀어나와 ㄷ자를 이뤄요.","평면: 세대 칸들이 한 줄로 곧게 가지 않고 중간에서 꺾여요.","p.33 의 반듯한 판 반복과 대비돼요. 부분은 규칙, 전체는 자유예요.","p.25 의 '규칙성보다 **시각적 밸런스** 추구' 가 아파트에서도 이어져요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"check","q":"**한자지구 아파트(Hansa)** 의 양 끝단이 부푼 까닭은 무엇일까요?","choices":["남측과 북측 양 끝단에 **클러스터 형식** 으로 단위세대를 배치해서","가운데에 큰 중정을 두어서","구조 기둥을 양 끝에만 세워서"],"a":0,"why":"볼륨감 있는 매스는 양 끝단에 클러스터 형식으로 단위세대를 배치한 결과예요."},{"kind":"warn","head":"헷갈리기 쉬운 점","items":["ㄷ자가 두 번 나와요.","p.25 알토 주택: L 또는 ㄷ자형으로 외부공간을 둘러싸요.","**한자지구 아파트(Hansa)**: 양 끝 클러스터 때문에 양 끝이 부푼 ㄷ자 매스예요."]},{"kind":"english","head":"논술 답안: 한자지구 아파트","en":"알토의 한자지구 아파트(베를린, 1957)는 콘크리트 슬래브 반복, 모듈화된 유닛, 줄눈의 격자형 패턴, 단일 색채로 단순성을 강조하면서, 양 끝단의 클러스터 형식 배치로 부푼 ㄷ자 매스와 꺾인 비대칭 형상을 이룬다.","ko":"앞 절반은 p.33(반복, 단순), 뒤 절반은 p.34(ㄷ자, 비대칭)예요.","tip":"'부분은 규칙, 전체는 자유' 한 줄을 먼저 떠올려요."}],"walk":{"head":null,"parts":[{"b":[0.04,0.08,0.448,0.443],"c":[0.0176,0.0578,0.4928,0.4873],"r":1.3484,"img":"img/U9/walk/p034_23_01.jpg","say":"사진: 양쪽 날개가 튀어나온 ㄷ자 외관을 올려다봤어요."},{"b":[0.52,0.145,0.462,0.3],"c":[0.4918,0.129,0.5082,0.332],"r":2.041,"img":"img/U9/walk/p034_23_02.jpg","say":"평면: 세대 칸들이 중간에서 꺾여 이어져요."},{"b":[0.1,0.585,0.76,0.045],"c":[0.062,0.5231,0.836,0.1689],"r":6.5996,"img":"img/U9/walk/p034_23_03.jpg","say":"ㄷ자: 양 끝단이 부풀고 가운데 깊이가 좁아요."},{"b":[0.1,0.645,0.76,0.1],"c":[0.062,0.6106,0.836,0.1689],"r":6.5996,"img":"img/U9/walk/p034_23_04.jpg","say":"까닭: 남측과 북측 양 끝단에 클러스터 형식으로 단위세대를 배치했어요."},{"b":[0.1,0.76,0.76,0.105],"c":[0.062,0.7281,0.836,0.1689],"r":6.5996,"img":"img/U9/walk/p034_23_05.jpg","say":"그리드를 벗어난 평면, 비틀어지고 꺾인 자유로운 비대칭 형상이에요."}]}},{"p":35,"title":"한자지구 아파트의 1층과 주변 (캡션 없는 슬라이드)","terms":["Hansa","Alvar Aalto","Frank Lloyd Wright","Organic Architecture","internationale Architektur","파이미오 결핵요양소","Mairea","헬싱키 대학 오디토리움"],"pass1":[{"kind":"say","lines":["9단원의 마지막 슬라이드예요. 글자 없이 사진 세 장뿐이에요.","앞 쪽에 이어지는 **한자지구 아파트(Hansa)** 사진으로 보여요.","캡션이 없으니 이름과 연도는 p.33 에서 가져와요."]},{"kind":"recap","items":["**프랭크 로이드 라이트(Frank Lloyd Wright)**: 상자를 깨고 자연 속으로 들어갔어요.","**알바 알토(Alvar Aalto)**: 국제주의에 나무와 사람을 더했어요.","두 사람 모두 **유기적 건축(Organic Architecture)** 이에요.","**국제주의 건축(internationale Architektur)** 과 대립되는 개념이에요."]}],"pass2":[{"kind":"points","head":"사진에서 보이는 것만","items":["왼쪽: 벽 판이 격자처럼 이어진 외벽이에요. 창이 규칙적으로 나 있어요.","1층은 벽 대신 둥근 기둥이 서 있고, 벽에 독일어 안내판이 걸려 있어요.","오른쪽 위: 1층의 열린 공간이에요. 흰 둥근 기둥들이 서 있고 바닥은 돌로 깔았어요.","오른쪽 아래: 나무 사이로 본 건물이에요. 1층 기둥 사이로 건너편이 보여요."]},{"kind":"look","walked":1}],"pass3":[{"kind":"warn","head":"이 쪽에서 조심할 점","items":["이 슬라이드에는 이름도 연도도 적혀 있지 않아요.","이름과 연도는 p.33 캡션에서 가져와요. **한자지구 아파트(Hansa)**, 독일 베를린, 1957년이에요.","안내판의 독일어 글자는 분양 안내예요. 시험과 상관없어요."]},{"kind":"check","q":"알토 작품을 연도 순서로 바르게 놓은 것은 무엇일까요?","choices":["파이미오 결핵요양소 → 빌라 마이레아 → 한자지구 아파트 → 헬싱키 대학 오디토리움","빌라 마이레아 → 파이미오 결핵요양소 → 헬싱키 대학 오디토리움 → 한자지구 아파트","한자지구 아파트 → 파이미오 결핵요양소 → 빌라 마이레아 → 헬싱키 대학 오디토리움"],"a":0,"why":"1933 → 1939 → 1957 → 1966 순서예요."}],"walk":{"head":null,"parts":[{"b":[0.035,0.226,0.372,0.652],"c":[0.0164,0.1934,0.4092,0.7172],"r":0.7607,"img":"img/U9/walk/p035_21_01.jpg","say":"왼쪽: 격자 판 외벽과 1층의 둥근 기둥, 안내판이에요."},{"b":[0.444,0.027,0.522,0.516],"c":[0.4179,0.0012,0.5742,0.5676],"r":1.3488,"img":"img/U9/walk/p035_21_02.jpg","say":"오른쪽 위: 흰 둥근 기둥이 선 1층의 열린 공간이에요."},{"b":[0.444,0.574,0.522,0.374],"c":[0.4179,0.5553,0.5742,0.4114],"r":1.861,"img":"img/U9/walk/p035_21_03.jpg","say":"오른쪽 아래: 나무 사이로 본 건물과 1층 기둥이에요."}]}}]};
